INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('les-indestructibles-erising-sun', 'GAMEBOYADVANCE', 'Les Indestructibles (E)(Rising Sun)', '2004', 'Action / Platformer', 'Helixe', '1', 'Platformer', 'Side-scrolling action-platformer with character-specific superpowers.', 'Stop Syndrome''s evil plot by using the Parr family''s unique abilities.', 'An action-packed superhero game based on Disney/Pixar''s The Incredibles.', 'Control Mr. Incredible, Elastigirl, Dash, and Violet. Master their iconic powers to battle robots and save Metroville in this faithful movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('les-razmoket---a-moi-la-fiesta-fpatience', 'GAMEBOYADVANCE', 'Les Razmoket - A Moi La Fiesta (F)(Patience)', '2002', 'Party', 'Software Creations', '4', 'Party Game', 'Board game style play with various party mini-games.', 'Win the ultimate party by outperforming other babies in competitive mini-games.', 'A fun, multi-player party game featuring the Rugrats characters.', 'Join Tommy, Chuckie, and the gang in Rugrats: Go Wild! (A Moi La Fiesta). Compete in silly challenges and explore vibrant worlds in this family-friendly GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('les-razmoket---voler-nest-pas-jouer-fpatience', 'GAMEBOYADVANCE', 'Les Razmoket - Voler n''est pas Jouer (F)(Patience)', '2002', 'Action / Platformer', 'Software Creations', '1', 'Platformer', 'Top-down exploration and puzzle-solving based on circus and park themes.', 'Complete various park missions to help the Rugrats find their lost toys.', 'A themed adventure game featuring the beloved Rugrats babies.', 'Navigate through park environments and solve baby-sized problems. Use teamwork to overcome obstacles and complete missions in this charming Rugrats adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('les-razmoket-rencontrent-les-delajungle-fpatience', 'GAMEBOYADVANCE', 'Les Razmoket rencontrent les Delajungle (F)(Patience)', '2003', 'Action / Platformer', 'Software Creations', '1', 'Platformer', 'Isometric action-adventure with character switching and item collection.', 'Survive the island and rescue the families from a mysterious threat.', 'A crossover adventure featuring the Rugrats and The Wild Thornberrys.', 'Experience the ultimate Nickelodeon crossover! Switch between the Rugrats and Thornberrys to explore the jungle, solve puzzles, and find a way home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-ride---friends-forever-usir-vg', 'GAMEBOYADVANCE', 'Let''s Ride - Friends Forever (U)(Sir VG)', '2009', 'Simulation', 'Tantalus Media', '1', 'Horse Simulation', 'Equestrian simulation focusing on horse care and competition riding.', 'Train your horse to win regional championships and build lasting bonds.', 'A realistic horse riding and care simulator for young enthusiasts.', 'Let''s Ride: Friends Forever lets you groom, feed, and train your own horse. Compete in show jumping and cross-country events to become a top rider.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-ride!-dreamer-utrashman', 'GAMEBOYADVANCE', 'Let''s Ride! Dreamer (U)(Trashman)', '2008', 'Simulation', 'Tantalus Media', '1', 'Horse Simulation', 'Life simulation and equestrian management with a focus on stable growth.', 'Manage your own stables while training horses for major competitions.', 'A deep horse stable management and training simulation.', 'Build your dream stable from the ground up. Manage finances, care for multiple horses, and prove your skills in the arena in this engaging equestrian sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-ride!-sunshine-stables-uindependent', 'GAMEBOYADVANCE', 'Let''s Ride! Sunshine Stables (U)(Independent)', '2007', 'Simulation', 'Tantalus Media', '1', 'Horse Simulation', 'Casual horse care and riding simulation in a sunny farm environment.', 'Enjoy daily farm life while caring for and riding various horses.', 'A relaxing horse-themed simulation game for mobile gamers.', 'Spend your days at Sunshine Stables. This GBA title offers a gentle approach to horse management, focusing on the joy of riding and daily animal care.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('licca-chan-no-oshare-nikki-jcaravan', 'GAMEBOYADVANCE', 'Licca-Chan no Oshare Nikki (J)(Caravan)', '2002', 'Simulation', 'TOMY', '1', 'Fashion Simulation', 'Lifestyle and fashion simulation based on the popular Japanese doll.', 'Dress up Licca-chan and manage her daily social diary and events.', 'A cute fashion and life simulation game featuring Licca-chan.', 'Become a stylist for Licca-chan! Choose the perfect outfits for different social occasions and document your stylish journey in her personal diary.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('liliput-oukoku-jrising-sun', 'GAMEBOYADVANCE', 'Liliput Oukoku (J)(Rising Sun)', '2002', 'Role-Playing', 'AlphaDream', '1', 'Japanese RPG', 'Kingdom management and strategy with tiny citizens.', 'Build and manage a miniature kingdom to ensure the happiness of your subjects.', 'A unique miniature world simulation and strategy game.', 'Guide the tiny people of Liliput Oukoku. Manage resources, build structures, and protect your tiny kingdom from threats in this creative GBA simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-buster-q-jpolla', 'GAMEBOYADVANCE', 'Little Buster Q (J)(Polla)', '2002', 'Puzzle', 'Game Freak', '1', 'Puzzle', 'Tactical board game with RPG elements and card-based combat.', 'Defeat rival teams in a strategic board-game format to become the champion.', 'A competitive tactical game with a focus on strategy and luck.', 'Little Buster Q combines board game mechanics with intense tactical battles. Choose your units wisely and use the terrain to outsmart your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-einsteins-urising-sun', 'GAMEBOYADVANCE', 'Little Einsteins (U)(Rising Sun)', '2006', 'Educational', 'Disney Interactive', '1', 'Educational Adventure', 'Educational mini-games and music-based puzzle solving.', 'Complete missions to learn about art, music, and teamwork with the team.', 'An educational adventure based on the Disney Junior series.', 'Join Leo, June, Quincy, and Annie on the GBA. Solve musical puzzles and learn about famous artwork in this engaging title for preschool-aged gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-league-baseball-2002-utrashman', 'GAMEBOYADVANCE', 'Little League Baseball 2002 (U)(Trashman)', '2001', 'Sports', 'Krome Studios', '2', 'Baseball Simulation', 'Sports simulation with realistic baseball mechanics and youth rosters.', 'Win the Little League World Series by mastering pitching and batting.', 'A dedicated baseball simulation focused on youth league play.', 'Step onto the diamond in Little League Baseball 2002. Experience authentic baseball gameplay with official Little League licensing and competitive season modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('little-patissier-cake-no-oshiro-jcaravan', 'GAMEBOYADVANCE', 'Little Patissier Cake no Oshiro (J)(Caravan)', '2003', 'Simulation', 'Taito', '1', 'Cooking Simulation', 'Cooking and management simulation focused on pastry making.', 'Run a successful cake shop and create beautiful desserts for customers.', 'A sweet and colorful pastry chef simulation game.', 'Design and bake the perfect cakes in Little Patissier. Manage your shop, learn new recipes, and satisfy your customers'' sweet tooth in this charming sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lizzie-mcguire---on-the-go-uhyperion', 'GAMEBOYADVANCE', 'Lizzie McGuire - On The Go (U)(Hyperion)', '2003', 'Action / Platformer', 'Vicarious Visions', '1', 'Platformer', 'Collection of mini-games and social simulation based on the TV show.', 'Navigate middle school life and complete various social challenges.', 'A fun mini-game compilation featuring Lizzie McGuire and her friends.', 'Join Lizzie in her everyday adventures. Play through various mini-games that reflect the humor and drama of being a teenager in this vibrant GBA title.');
