INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---back-in-action-umode7', 'GAMEBOYADVANCE', 'Looney Tunes - Back in Action (U)(Mode7)', '2003', 'Action / Platformer', 'Warthog Games', '1', 'Platformer', 'Isometric action-adventure with character switching and gadgets.', 'Find the Blue Monkey diamond to stop the ACME Corporation''s evil plan.', 'An action game based on the Looney Tunes movie of the same name.', 'Control Bugs Bunny and Daffy Duck. Use their unique skills to navigate movie sets, fight enemies, and solve puzzles in this hilarious GBA adventure.');
