INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('love-hina-advance-jeurasia', 'GAMEBOYADVANCE', 'Love Hina Advance (J)(Eurasia)', '2003', 'Adventure', 'Love Hina Team', '1', 'Visual Novel', 'Visual novel with dating simulation and school-life elements.', 'Build relationships with the girls at the Hinata Inn while studying.', 'A romantic adventure based on the popular Love Hina anime.', 'Experience the life of Keitaro in Love Hina Advance. Make pivotal choices to find love and pass the Tokyo U exams in this charming Japanese sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-luke---wanted!-elightforce', 'GAMEBOYADVANCE', 'Lucky Luke - Wanted! (E)(Lightforce)', '2002', 'Action / Platformer', 'Virgin Interactive', '1', 'Platformer', 'Side-scrolling action platformer with shooting and puzzle elements.', 'Capture the most notorious outlaws in the Wild West as Lucky Luke.', 'A cowboy adventure based on the classic European comic series.', 'Ride Jolly Jumper and take on the Daltons. Use your quick-draw skills and platforming agility to bring justice to the frontier in this colorful GBA game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lufia---the-ruins-of-lore-ueurasia', 'GAMEBOYADVANCE', 'Lufia - The Ruins Of Lore (U)(Eurasia)', '2001', 'Role-Playing', 'Neverland', '1', 'Japanese RPG', 'Traditional turn-based RPG with monster capture and party management.', 'Discover the ancient secrets of the ruins and save the world from ruin.', 'A deep and classic RPG experience in the Lufia series.', 'Lufia: The Ruins of Lore features a compelling story, strategic turn-based battles, and a unique system for catching and training monster allies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luigi-is-hard-t-posed-and-has-no-kart-by-neweegee', 'GAMEBOYADVANCE', 'Luigi is hard T-posed and has no kart by Neweegee', '2023', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', 'Glitch-based racing modification with broken animations and karts.', 'Attempt to finish races despite the character''s broken T-pose state.', 'A humorous fan-made modification for Mario Kart Super Circuit.', 'Experience the absurdity of Luigi in a permanent T-pose. This bizarre hack removes Luigi''s kart and freezes his animation for a hilarious racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar-legend-jeurasia', 'GAMEBOYADVANCE', 'Lunar Legend (J)(Eurasia)', '2002', 'Role-Playing', 'Game Arts', '1', 'Japanese RPG', 'Turn-based JRPG with a focus on storytelling and traditional combat.', 'Journey with Alex to become a Dragonmaster and save the goddess.', 'A portable reimagining of the classic Lunar: Silver Star Story.', 'Lunar Legend brings the magic of the Lunar series to GBA. Experience a touching story, beautiful pixel art, and strategic turn-based combat in this classic RPG.');
