INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m&ms-blast!-ulightforce', 'GAMEBOYADVANCE', 'M&M''s Blast! (U)(Lightforce)', '2001', 'Action / Puzzle', 'Artificial Mind & Movement', '1', 'Puzzle Action', 'First-person perspective shooting and puzzle-solving mechanics.', 'Blast through levels by hitting target M&M''s while avoiding obstacles.', 'A fast-paced shooter and puzzle game featuring M&M''s characters.', 'M&M''s Blast! brings arcade-style action to the GBA. Navigate through colorful levels and use quick reflexes to clear targets in this fun and accessible candy-themed adventure.');
