INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('made-in-wario-jeurasia', 'GAMEBOYADVANCE', 'Made in Wario (J)(Eurasia)', '2003', 'Action / Mini-Games', 'Nintendo', '1', 'Microgames', 'Rapid-fire mini-game collection with surreal humor and quick reflexes.', 'Clear as many "micro-games" as possible within a few seconds each.', 'The original Japanese version of the cult classic WarioWare series.', 'Made in Wario (WarioWare, Inc.) features hundreds of 5-second challenges. Test your reflexes and humor in this fast-paced, addictive, and bizarre GBA masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magi-nation-jcezar', 'GAMEBOYADVANCE', 'Magi Nation (J)(Cezar)', '2002', 'Role-Playing', 'Interactive Imagination', '1', 'Japanese RPG', 'Creature-collecting RPG with turn-based card-like battle mechanics.', 'Save the Moonlands by collecting and training powerful Dream Creatures.', 'A deep and atmospheric RPG based on the Magi Nation card game.', 'Magi Nation for GBA offers a unique creature-summoning experience. Explore a vast world, collect animite, and master strategic battles in this classic Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-fengshen-jcezar', 'GAMEBOYADVANCE', 'Magical Fengshen (J)(Cezar)', '2001', 'Action / Role-Playing', 'Square', '1', 'Action RPG', 'Strategic RPG with turn-based combat based on Chinese mythology.', 'Defeat mystical entities and navigate a fantasy world using magic.', 'A tactical adventure game inspired by the legend of Fengshen Bang.', 'Magical Fengshen (Houshin Engi) brings tactical combat to the GBA. Command a party of mythical heroes and use powerful magic to fulfill the ancient prophecy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-vacation-jeurasia', 'GAMEBOYADVANCE', 'Magical Vacation (J)(Eurasia)', '2001', 'Role-Playing', 'Brownie Brown', '1', 'Japanese RPG', 'Turn-based JRPG with elemental magic and school-life elements.', 'Master elemental spells and solve the mystery of the magical school.', 'A beautifully animated original RPG developed by Brownie Brown.', 'Magical Vacation is a GBA cult classic. Join a group of magic students on an interdimensional journey featuring stunning pixel art and a deep elemental combat system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-detective-jeurasia', 'GAMEBOYADVANCE', 'Mahjong Detective (J)(Eurasia)', '2002', 'Board Game', 'Hudson Soft', '1', 'Mahjong', 'Traditional Japanese Mahjong with a detective-story narrative.', 'Solve crimes by winning Mahjong matches against various suspects.', 'A unique blend of Mahjong simulation and mystery investigation.', 'Mahjong Detective challenges your tiles skills and your brain. Follow the clues and outplay your opponents in this engaging Japanese Mahjong adventure.');
