INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mail-de-cute-jindependent', 'GAMEBOYADVANCE', 'Mail de Cute (J)(Independent)', '2001', 'Simulation', 'Media Rings', '1', 'Communication Simulation', 'Social simulation and virtual mail/message based adventure.', 'Interact with cute characters through a virtual messaging system.', 'A unique communication-based simulation game for the Japanese market.', 'Mail de Cute offers a creative take on the virtual pet/social genre. Send and receive messages to build friendships with adorable characters on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-league-baseball-2k7-uomgba', 'GAMEBOYADVANCE', 'Major League Baseball 2K7 (U)(OMGba)', '2007', 'Sports', 'Kush Games', '2', 'Baseball Simulation', 'Realistic baseball simulation with professional rosters and tactics.', 'Win the World Series by mastering pitching, hitting, and fielding.', 'The 2K7 edition of the professional Major League Baseball series.', 'MLB 2K7 brings the 2007 season to your pocket. Featuring official rosters and realistic stadium action, it''s a solid choice for baseball fans on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manga-ka-debut-monogatari-j2ch', 'GAMEBOYADVANCE', 'Manga-ka Debut Monogatari (J)(2CH)', '2001', 'Simulation', 'Taito', '1', 'Manga Creation', 'Career simulation focusing on the life of a professional manga artist.', 'Create hit manga series by managing time, drawing, and storytelling.', 'A unique simulation game about the Japanese manga industry.', 'Manga-ka Debut Monogatari lets you live the life of an artist. Manage your schedule, develop your art skills, and try to get published in this deep career sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('maniac-racers-advance-epatience', 'GAMEBOYADVANCE', 'Maniac Racers Advance (E)(Patience)', '2002', 'Racing', 'Crawfish Interactive', '4', 'Arcade Racing', 'Top-down arcade racing with high-speed turns and aggressive AI.', 'Win championship races to unlock faster vehicles and new tracks.', 'A fast-paced top-down racer focused on drift mechanics and speed.', 'Maniac Racers Advance offers classic arcade racing for GBA. Master tight corners and outpace your rivals in this high-energy, top-down driving challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('manic-miner-eeurasia', 'GAMEBOYADVANCE', 'Manic Miner (E)(Eurasia)', '2001', 'Action / Platformer', 'Tony Gibson', '1', 'Classic Platformer', 'Classic 2D platforming with precision jumping and oxygen management.', 'Collect all flashing items in each cavern before your air runs out.', 'A faithful handheld port of the legendary 8-bit platformer.', 'Manic Miner brings retro difficulty to the GBA. Navigate dangerous caverns filled with surreal enemies in this perfectly preserved 8-bit gaming classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marble-madness-&-klax-utrashman', 'GAMEBOYADVANCE', 'Marble Madness & Klax (U)(Trashman)', '2001', 'Puzzle', 'Atari Games', '2', 'Arcade Puzzle', 'Two-in-one arcade puzzle collection featuring physics and tile-matching.', 'Guide the marble to the exit and stack tiles to clear rows.', 'A double pack featuring the classics Marble Madness and Klax.', 'Experience two arcade legends on one cart. Master the physics-based puzzles of Marble Madness and the addictive tile-stacking strategy of Klax on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('march-of-the-penguins-eindependent', 'GAMEBOYADVANCE', 'March of the Penguins (E)(Independent)', '2005', 'Educational', 'Unknown', '1', 'Educational Adventure', 'Lemmings-style puzzle platforming with environmental interaction.', 'Guide the penguin colony safely across the Antarctic ice to their destination.', 'A charming puzzle game based on the award-winning documentary film.', 'March of the Penguins challenges your logic and timing. Help the penguins survive the harsh winter by building bridges and clearing paths in this unique GBA puzzler.');
