INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marheaven---knockin-on-heavens-door-jsupplex', 'GAMEBOYADVANCE', 'Marheaven - Knockin'' on Heaven''s Door (J)(Supplex)', '2003', 'Role-Playing', 'Victor Interactive', '1', 'Japanese RPG', '2D arena fighting game based on the Mar (MÄR) anime series.', 'Win the War Games by defeating rival chess soldiers in combat.', 'An action-packed fighter featuring characters from the MÄR universe.', 'Marheaven: Knockin'' on Heaven''s Door brings anime battles to the GBA. Use unique "ARM" weapons and magical abilities to dominate the arena and save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marie-elie-&-anis-no-atelier---soyokaze-kara-no-dengon-jpolla', 'GAMEBOYADVANCE', 'Marie, Elie & Anis No Atelier - Soyokaze Kara No Dengon (J)(Polla)', '2002', 'Role-Playing', 'Gust', '1', 'Japanese RPG', 'Crafting-based RPG and social simulation with item management.', 'Collect ingredients and synthesize items to run a successful atelier.', 'A portable entry in the acclaimed Atelier series featuring three heroines.', 'Marie, Elie & Anis No Atelier offers deep alchemy mechanics. Explore, fight monsters, and create magical items in this charming Japanese GBA RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-in-sonic-battle', 'GAMEBOYADVANCE', 'Mario in Sonic Battle', '2003', 'Fighting', 'Sonic Team', '2', 'Fighting', 'Fast-paced 2.5D arena fighting using modified Sonic Battle mechanics.', 'Defeat opponents in arena combat using Mario''s specialized moves.', 'A unique crossover modification featuring Mario in the Sonic Battle engine.', 'Mario in Sonic Battle! brings the Mushroom Kingdom hero to the high-speed arena. Master Mario’s fireballs and jumps in this explosive combat modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-fixed-circuit', 'GAMEBOYADVANCE', 'Mario Kart Fixed Circuit', '2001', 'Racing', 'Nintendo', '4', 'Arcade Racing', 'Mode-7 style kart racing with revised track layouts and fixed logic.', 'Win the racing cup by mastering turns and using classic power-ups.', 'A modified version of Mario Kart Super Circuit with track fixes.', 'Mario Kart Fixed Circuit offers a refined racing experience. Enjoy the classic Super Circuit gameplay with improved track design and polished racing mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-r-advance', 'GAMEBOYADVANCE', 'Mario Kart R Advance', '2001', 'Racing', 'Nintendo', '4', 'Arcade Racing', 'High-speed kart racing with custom characters and adjusted difficulty.', 'Finish first in every race to unlock secret cups and faster speeds.', 'A fan-made enhancement of the original Mario Kart Super Circuit.', 'Mario Kart R Advance adds a fresh layer of challenge to the GBA. Experience new racing dynamics and competitive AI in this refined version of the classic racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-super-circuit-xxl', 'GAMEBOYADVANCE', 'Mario Kart Super Circuit XXL', '2001', 'Racing', 'Nintendo', '4', 'Arcade Racing', 'Kart racing with massive character sprites and experimental visuals.', 'Win the championship while testing the limits of GBA sprite scaling.', 'A visual modification that scales up the racers for a "larger" experience.', 'Mario Kart Super Circuit XXL provides a unique perspective on GBA racing. Features oversized character sprites that change the feel of the classic Mode-7 tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-kart-xxl-tech-demo-apr-17th-2004', 'GAMEBOYADVANCE', 'Mario Kart XXL (Tech Demo) (Apr 17th 2004)', '2004', 'Racing', 'Nintendo', '4', 'Tech Demo', 'Technical demonstration showcasing advanced 3D scaling and rotation.', 'Explore the prototype racing engine and technical capabilities.', 'A rare 2004 tech demo showing early GBA hardware potential.', 'Mario Kart XXL (Tech Demo) is a piece of gaming history. Witness the experimental technology behind GBA racing graphics in this fascinating unreleased prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel---ultimate-alliance-urising-sun', 'GAMEBOYADVANCE', 'Marvel - Ultimate Alliance (U)(Rising Sun)', '2006', 'Action / Role-Playing', 'Vicarious Visions', '1', 'Action RPG', 'Isometric action RPG with team-based combat and superhero upgrades.', 'Stop Dr. Doom and the Masters of Evil from conquering the world.', 'A massive crossover RPG featuring dozens of Marvel superheroes.', 'Marvel: Ultimate Alliance lets you form your dream team of heroes. Use the powers of Spider-Man, Wolverine, and more in this deep, action-packed GBA RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-ultimate-alliance-eindependent', 'GAMEBOYADVANCE', 'Marvel Ultimate Alliance (E)(Independent)', '2006', 'Action / Role-Playing', 'Vicarious Visions', '1', 'Action RPG', 'Isometric action RPG with team-based combat and superhero upgrades.', 'Stop Dr. Doom and the Masters of Evil from conquering the world.', 'A massive crossover RPG featuring dozens of Marvel superheroes.', 'Marvel: Ultimate Alliance lets you form your dream team of heroes. Use the powers of Spider-Man, Wolverine, and more in this deep, action-packed GBA RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-kate-and-ashley---girls-night-out-uvenom', 'GAMEBOYADVANCE', 'Mary-Kate and Ashley - Girls Night Out (U)(Venom)', '2003', 'Simulation', 'N-Space', '1', 'Social Simulation', 'Social simulation and party mini-games focused on teen lifestyle.', 'Plan the perfect girls'' night out by winning fashion and social games.', 'A vibrant collection of mini-games starring the Olsen twins.', 'Join Mary-Kate and Ashley for a night of fun. Complete fashion challenges and social puzzles to become the ultimate party planner on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-kate-and-ashley---sweet-16-upatience', 'GAMEBOYADVANCE', 'Mary-Kate and Ashley - Sweet 16 (U)(Patience)', '2002', 'Simulation', 'N-Space', '1', 'Social Simulation', 'Driving and social simulation based on getting a driver''s license.', 'Complete driving tasks and social missions to celebrate your 16th birthday.', 'A lifestyle adventure game featuring the Olsen twins.', 'Experience the milestone of turning 16 with Mary-Kate and Ashley. Drive around town, shop, and hang out with friends in this teen-focused GBA sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('masters-of-the-universe---he-man---power-of-grayskull-uvenom', 'GAMEBOYADVANCE', 'Masters of the Universe - He-Man - Power of Grayskull (U)(Venom)', '2002', 'Action / Adventure', 'TDK Mediactive', '1', 'Action Adventure', 'Side-scrolling beat ''em up and action-adventure.', 'Defeat Skeletor and protect the secrets of Castle Grayskull.', 'A heroic action game based on the He-Man and the MOTU series.', 'By the power of Grayskull! Take control of He-Man in this classic GBA brawler. Battle through the wild lands of Eternia to stop Skeletor’s evil army.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mat-hoffmans-pro-bmx-erocket', 'GAMEBOYADVANCE', 'Mat Hoffman''s Pro BMX (E)(Rocket)', '2001', 'Sports', 'Z-Axis', '2', 'Extreme Sports', 'Isometric extreme sports simulation with trick combos and objectives.', 'Complete pro-level BMX tricks to earn points and unlock new riders.', 'A high-flying BMX simulation featuring the legendary Mat Hoffman.', 'Mat Hoffman''s Pro BMX delivers arcade-style extreme sports. Master manuals, grinds, and flips across diverse urban parks in this addictive GBA title.');
