INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mat-hoffmans-pro-bmx-2-ueurasia', 'GAMEBOYADVANCE', 'Mat Hoffman''s Pro BMX 2 (U)(Eurasia)', '2002', 'Sports', 'Z-Axis', '2', 'Extreme Sports', 'Enhanced BMX simulation with more tricks and bigger environments.', 'Win the pro tour by executing massive aerial combos and stunts.', 'The improved sequel to the popular handheld BMX racing series.', 'Mat Hoffman''s Pro BMX 2 takes the action higher. Featuring more riders and refined controls, it''s the definitive BMX experience for extreme sports fans on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matantei-loki-ragnarok-jrising-sun', 'GAMEBOYADVANCE', 'Matantei Loki Ragnarok (J)(Rising Sun)', '2003', 'Adventure', 'Asmik Ace', '1', 'Visual Novel', 'Mystery adventure and puzzle-solving based on the anime series.', 'Solve supernatural crimes by gathering clues and talking to witnesses.', 'A Japanese detective adventure based on the Loki Ragnarok manga.', 'Join the Mythical Detective Loki on GBA. Solve intricate mysteries and navigate a supernatural storyline in this engaging Japanese visual adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('matchbox---cross-town-heroes-epatientz', 'GAMEBOYADVANCE', 'Matchbox - Cross Town Heroes (E)(Patientz)', '2003', 'Action / Racing', 'Atomic Planet', '1', 'Arcade Action', 'Mission-based driving and rescue simulation for younger players.', 'Save the city by responding to emergencies in Matchbox vehicles.', 'A heroic driving adventure featuring official Matchbox cars.', 'Matchbox: Cross Town Heroes lets you be the hero. Drive fire trucks and police cars to solve problems and save citizens in this fun GBA driving game.');
