INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('math-patrol---the-kleptoid-threat-usir-vg', 'GAMEBOYADVANCE', 'Math Patrol - The Kleptoid Threat (U)(Sir VG)', '2002', 'Educational', 'Lightspan', '1', 'Educational', 'Educational puzzle-adventure focused on mathematics.', 'Solve math equations and puzzles to stop the Kleptoids from stealing knowledge.', 'A fun educational game that teaches basic and advanced math.', 'Math Patrol makes learning fun! Use your math skills to outsmart the Kleptoids and solve the mystery in this engaging educational GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mawaru-made-in-wario-jwrg', 'GAMEBOYADVANCE', 'Mawaru Made in Wario (J)(WRG)', '2004', 'Action / Mini-Games', 'Nintendo', '1', 'Microgames', 'Motion-controlled mini-game collection using a built-in gyro sensor.', 'Clear hundreds of bizarre micro-games by physically rotating the GBA.', 'The innovative "Twisted" entry in the WarioWare series.', 'Mawaru Made in Wario (WarioWare Twisted!) is a revolution in handheld play. Spin your GBA to solve wacky challenges in this highly addictive and unique masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('max-payne-umode7', 'GAMEBOYADVANCE', 'Max Payne (U)(Mode7)', '2003', 'Action / Shooter', 'Neo Software', '1', 'Third-Person Shooter', 'Isometric third-person shooter with "Bullet Time" mechanics.', 'Fight through the criminal underworld to avenge Max''s family.', 'A technically impressive handheld port of the gritty noir shooter.', 'Max Payne Advance brings slow-motion gunplay to the GBA. Experience the dark story and intense tactical shooting that defined the series.');
