INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medarot-navi---kabuto-version-jeurasia', 'GAMEBOYADVANCE', 'Medarot Navi - Kabuto Version (J)(Eurasia)', '2002', 'Role-Playing', 'Natsume', '1', 'Japanese RPG', 'Tactical turn-based RPG with grid-based movement and exploration.', 'Navigate the Kasumi school and defeat the mysterious Robattle rivals.', 'A strategy-heavy entry in the Medarot series with anime aesthetics.', 'Medarot Navi: Kabuto Version focuses on tactical positioning. Lead your team in grid-based combat and uncover the secrets of the school in this Japanese GBA exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medarot-navi---kuwagata-version-jeurasia', 'GAMEBOYADVANCE', 'Medarot Navi - Kuwagata Version (J)(Eurasia)', '2002', 'Role-Playing', 'Natsume', '1', 'Japanese RPG', 'Tactical turn-based RPG with grid-based movement and exploration.', 'Navigate the Kasumi school and defeat the mysterious Robattle rivals.', 'A strategy-heavy entry in the Medarot series with anime aesthetics.', 'Medarot Navi: Kuwagata Version delivers deep strategy RPG gameplay. Manage your units carefully and use specialized parts to dominate the tactical battlefield.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meet-the-robinsons-esupplex', 'GAMEBOYADVANCE', 'Meet the Robinsons (E)(sUppLeX)', '2007', 'Action / Adventure', 'Amaze Entertainment', '1', 'Adventure', '2D side-scrolling action-platformer with gadget-based puzzles.', 'Travel to the future to stop the Bowler Hat Guy and save the family.', 'An adventure game based on the Disney animated film.', 'Join Wilbur Robinson on a high-tech quest! Use futuristic gadgets to solve puzzles and defeat robotic enemies in this fun movie-based GBA adventure.');
