INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-chip-challenge-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Chip Challenge (Virtual Console)', '2004', 'Card Game', 'Capcom', '1', 'Strategy Card Game', 'Deck-building strategy game with automated turn-based combat.', 'Win the Battle Chip tournament by building the most efficient deck.', 'A strategic spin-off of the Mega Man Battle Network series.', 'Mega Man Battle Chip Challenge focuses on deck management. Collect powerful chips and program your NetNavi to win the ultimate tournament on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network (Virtual Console)', '2001', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Real-time grid-based combat and RPG exploration in a digital world.', 'Stop the criminal organization WWW and save the internet as MegaMan.EXE.', 'The first entry in the legendary tactical RPG series.', 'Mega Man Battle Network revolutionizes the RPG genre. Combine fast-paced card-like combat with digital world exploration in this acclaimed GBA classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-2-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network 2 (Virtual Console)', '2002', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Real-time grid-based combat with expanded chips and NetNavi styles.', 'Defeat the Net-Mafia Gospel and prevent a global digital collapse.', 'The highly-polished sequel with improved combat and world design.', 'Mega Man Battle Network 2 introduces the Style Change system. Master new battle strategies and explore a larger internet in this fan-favorite GBA sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-3-blue-version-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network 3 Blue Version (Virtual Console)', '2003', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Strategic combat with a focus on the Navi Cust system and net exploration.', 'Solve the mystery of the Alpha prototype and stop the WWW''s return.', 'Often considered the peak of the series, featuring the Blue version.', 'Battle Network 3 Blue Version offers exclusive chips and a unique boss. Dive into the deep Navi Customizer system and experience an epic story on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-3-white-version-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network 3 White Version (Virtual Console)', '2003', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Strategic combat with a focus on the Navi Cust system and net exploration.', 'Solve the mystery of the Alpha prototype and stop the WWW''s return.', 'Often considered the peak of the series, featuring the White version.', 'Battle Network 3 White Version provides a classic challenge with exclusive battle content. Build the ultimate folder and save the digital world once again.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-4-blue-moon-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network 4 Blue Moon (Virtual Console)', '2004', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Real-time combat featuring the "Soul Unison" system and tournament arcs.', 'Win the international tournaments and stop the asteroid threat.', 'The fourth entry featuring the Blue Moon version and exclusive souls.', 'Battle Network 4: Blue Moon introduces the Double Soul mechanic. Compete in thrilling tournaments and customize your playstyle in this vibrant GBA RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-4-red-sun-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network 4 Red Sun (Virtual Console)', '2004', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Real-time combat featuring the "Soul Unison" system and tournament arcs.', 'Win the international tournaments and stop the asteroid threat.', 'The fourth entry featuring the Red Sun version and exclusive souls.', 'Battle Network 4: Red Sun offers unique tournament paths and powerful soul transformations. Master the "Full Synchro" state to dominate digital battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-5-team-colonel-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network 5 Team Colonel (Virtual Console)', '2004', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Tactical grid-based RPG with team management and liberation missions.', 'Lead a team of NetNavis to liberate the internet from Nebula''s control.', 'The fifth entry featuring the Team Colonel leadership.', 'Battle Network 5: Team Colonel introduces tactical liberation missions. Command a diverse team of Navis and use strategic planning to save the net.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-battle-network-5-team-protoman-virtual-console', 'GAMEBOYADVANCE', 'Mega Man Battle Network 5 Team ProtoMan (Virtual Console)', '2005', 'Action / Role-Playing', 'Capcom', '1', 'Action RPG', 'Tactical grid-based RPG with team management and liberation missions.', 'Lead a team of NetNavis to liberate the internet from Nebula''s control.', 'The fifth entry featuring the Team ProtoMan leadership.', 'Battle Network 5: Team ProtoMan offers a different set of allies and souls. Lead ProtoMan''s squad and master the tactical elements of this deep GBA RPG.');
