INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-in-sonic-battle', 'GAMEBOYADVANCE', 'Mega Man in Sonic Battle', '2003', 'Fighting', 'Homebrew', '2', 'ROM Hack', 'Isometric arena fighting with modified character sprites and move sets.', 'Defeat opponents in 3D combat using Mega Man''s classic buster shots.', 'A creative crossover hack bringing Mega Man into the Sonic Battle engine.', 'Mega Man in Sonic Battle! combines classic Blue Bomber action with high-speed arena combat. Use your arm cannon to dominate the battlefield in this unique GBA character swap.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x-in-sonic-battle', 'GAMEBOYADVANCE', 'Mega Man X in Sonic Battle', '2003', 'Fighting', 'Homebrew', '2', 'ROM Hack', 'Isometric arena fighting with high-mobility dashing and saber combat.', 'Master X’s armor abilities to win the arena-based tournament.', 'A character modification featuring Mega Man X in the Sonic Battle universe.', 'Experience the power of the Maverick Hunter in Mega Man X in Sonic Battle. Featuring high-speed dashes and powerful charged shots in an isometric 3D fighting environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-2-restoration', 'GAMEBOYADVANCE', 'Mega Man Zero 2 Restoration', '2003', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', 'High-speed 2D action-platforming with restored audio and visuals.', 'Defeat Elpizo and the Neo Arcadian forces while enjoying original assets.', 'A fan-made restoration that brings back Japanese voice acting and blood effects.', 'Mega Man Zero 2 Restoration is the definitive way to play. Enjoy the intense difficulty and tight platforming with all the original Japanese audio and uncensored visuals intact.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-2-revisited-antigrind', 'GAMEBOYADVANCE', 'Mega Man Zero 2 Revisited (antigrind)', '2003', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', 'Side-scrolling action focused on boss battles without the need for grinding.', 'Unlock all skills and upgrades quickly to focus on the core combat.', 'A quality-of-life hack that removes the grind for weapons and forms.', 'Mega Man Zero 2 Revisited (Antigrind) streamlines the experience. Level up your weapons instantly and focus on mastering the challenging boss patterns in this balanced GBA hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-2-revisited-easyexskill', 'GAMEBOYADVANCE', 'Mega Man Zero 2 Revisited (easyexskill)', '2003', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', 'Side-scrolling action where EX Skills are unlocked regardless of rank.', 'Defeat bosses and obtain their special moves without needing an "S" or "A" rank.', 'A modification that makes powerful EX skills accessible to all players.', 'Mega Man Zero 2 Revisited (Easy EX Skill) allows you to collect the best abilities without the stress of high-rank requirements. Perfect for players who want the full arsenal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-2-revisited-elf-penalty', 'GAMEBOYADVANCE', 'Mega Man Zero 2 Revisited (elf penalty)', '2003', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', 'Hardcore 2D action-platforming where Cyber-elf usage is strictly penalized.', 'Complete the game with maximum challenge by avoiding or being punished for Elves.', 'A difficulty modification for veteran players seeking the ultimate challenge.', 'Mega Man Zero 2 Revisited (Elf Penalty) targets the most skilled players. Experience the game with a scoring system that demands perfection and minimal reliance on assistance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-3-restoration', 'GAMEBOYADVANCE', 'Mega Man Zero 3 Restoration', '2004', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', 'Precision 2D platforming with restored Japanese content and audio.', 'Stop Dr. Weil and Omega while enjoying the original atmosphere.', 'A comprehensive restoration of the third Mega Man Zero title.', 'Mega Man Zero 3 Restoration brings back the missing voice clips and original blood effects. Dive into the best-regarded entry of the series with all its artistic integrity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-4-restoration', 'GAMEBOYADVANCE', 'Mega Man Zero 4 Restoration', '2005', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', '2D action-platforming with weather mechanics and restored features.', 'Defeat the Einherjar Eight Warriors and save the settlement.', 'A fan restoration for the final chapter of the Zero saga on GBA.', 'Mega Man Zero 4 Restoration ensures the finale is played as intended. Includes restored Japanese voice acting and minor visual fixes for a more immersive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-zero-restoration', 'GAMEBOYADVANCE', 'Mega Man Zero Restoration', '2002', 'Action / Platformer', 'Homebrew', '1', 'ROM Hack', '2D action-platforming with a focus on saber combat and agility.', 'Escape Neo Arcadia and join the Resistance in the first chapter.', 'A restoration of the original Mega Man Zero, bringing back cut content.', 'Mega Man Zero Restoration restores the original atmosphere of Zero''s debut. Battle through difficult stages with the original audio cues and uncensored combat effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-moemon-firered-v1111e', 'GAMEBOYADVANCE', 'Mega Moemon FireRed v1.1.11e', '2016', 'Role-Playing', 'Homebrew', '1', 'ROM Hack', 'Turn-based creature collection with "Moemon" (anthropomorphic) sprites.', 'Catch and train all Moemon while conquering the Kanto region.', 'A popular visual overhaul of Pokémon FireRed featuring cute characters.', 'Mega Moemon FireRed transforms the classic Pokémon experience. Every monster is replaced with a charming "Moemon" sprite, offering a fresh visual take on the journey.');
