INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-&-bass-ewc', 'GAMEBOYADVANCE', 'MegaMan & Bass (E)(wC)', '2003', 'Action / Platformer', 'Capcom', '1', 'Action Platformer', 'Traditional 2D action-platforming with character-switching mechanics.', 'Defeat King and his robot army using either Mega Man or Bass.', 'A handheld port of the classic Super Famicom action game.', 'MegaMan & Bass lets you choose your playstyle. Use Mega Man''s slide or Bass''s double jump to navigate tough levels and defeat challenging robot masters on the GBA.');
