INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-zero-uvenom', 'GAMEBOYADVANCE', 'MegaMan Zero (U)(Venom)', '2002', 'Action / Platformer', 'Capcom', '1', 'Action Platformer', 'High-speed 2D action-platformer with a focus on melee saber combat.', 'Awaken from stasis to lead the Resistance against Neo Arcadia.', 'The challenging debut of the legendary Mega Man Zero saga.', 'MegaMan Zero delivers intense, high-stakes action. Master the Z-Saber and navigate brutal levels in this hardcore GBA classic that redefined handheld platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-zero-2-epatience', 'GAMEBOYADVANCE', 'MegaMan Zero 2 (E)(Patience)', '2003', 'Action / Platformer', 'Capcom', '1', 'Action Platformer', 'Side-scrolling action-platformer with weapon leveling and "Forms" system.', 'Pursue the rouge leader Elpizo and prevent a global energy crisis.', 'The refined sequel with expanded combat and customization.', 'MegaMan Zero 2 introduces the Power Form and EX Skills. Experience some of the toughest boss battles on the GBA in this fast-paced, stylish action sequel.');
