INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-liebe-angel-league-jperversion', 'GAMEBOYADVANCE', 'Meine Liebe (Angel League) (J)(PERVERSiON)', '2004', 'Adventure', 'Gainax', '1', 'Visual Novel', 'Visual novel with dating simulation and political intrigue.', 'Navigate high-society school life and build romantic relationships.', 'A stylish Japanese romantic adventure set in a fictional academy.', 'Meine Liebe offers a blend of drama and romance. Make pivotal social choices to influence your standing in the Angel League in this elegant GBA visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meine-tierarztpraxis-erising-sun', 'GAMEBOYADVANCE', 'Meine Tierarztpraxis (E)(Rising Sun)', '2007', 'Simulation', 'Tate Interactive', '1', 'Veterinary Simulation', 'Veterinary simulation with diagnosis and animal care mini-games.', 'Run a successful clinic and treat various domestic and wild animals.', 'A realistic and educational animal care simulation.', 'Meine Tierarztpraxis lets you fulfill your dream of becoming a vet. Learn about animal health, manage your practice, and heal pets in this detailed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meitantei-conan---atasuki-no-monument-jsupplex', 'GAMEBOYADVANCE', 'Meitantei Conan - Atasuki no Monument (J)(Supplex)', '2004', 'Adventure', 'Banpresto', '1', 'Adventure', 'Mystery adventure with puzzle-solving and interrogation mechanics.', 'Solve a series of complex cases as the brilliant child detective Conan.', 'A detective adventure game based on the Detective Conan anime.', 'Meitantei Conan: Atasuki no Monument challenges your logic. Gather clues, talk to suspects, and solve the riddle of the monument in this engaging Japanese quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('men-in-black---the-series-eeurasia', 'GAMEBOYADVANCE', 'Men in Black - The Series (E)(Eurasia)', '2001', 'Action', 'Vicarious Visions', '1', 'Action', 'Side-scrolling action brawler with specialized alien-fighting gadgets.', 'Protect Earth from rogue extraterrestrials using MiB technology.', 'An action-packed title based on the Men in Black animated series.', 'Suit up as the MIB! Use iconic weapons like the Noisy Cricket to neutralize alien threats and maintain planetary secret in this classic GBA action game.');
