INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-max-2-kai-jrising-sun', 'GAMEBOYADVANCE', 'Metal Max 2 Kai (J)(Rising Sun)', '2001', 'Role-Playing', 'Crea-Tech', '1', 'Japanese RPG', 'Post-apocalyptic RPG with tank customization and turn-based combat.', 'Hunt down outlaws and upgrade your vehicle in a wasteland world.', 'A gritty and deep Japanese RPG featuring heavy vehicular combat.', 'Metal Max 2 Kai is a cult classic. Explore a destroyed world, build the ultimate battle tank, and fight massive mechanical bosses in this non-linear GBA RPG.');
