INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid---fusion-eflashadvance', 'GAMEBOYADVANCE', 'Metroid - Fusion (E)(FlashAdvance)', '2002', 'Action / Adventure', 'Nintendo R&D1', '1', 'Action Adventure', 'Atmospheric "Metroidvania" with story-driven exploration and horror elements.', 'Investigate the research station and survive the parasitic X infection.', 'A cinematic and intense entry in the Metroid franchise.', 'Metroid Fusion blends tight exploration with a sense of dread. Evade the powerful SA-X and reclaim your powers in this atmospheric GBA masterpiece.');
