INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid---zero-mission-erising-sun', 'GAMEBOYADVANCE', 'Metroid - Zero Mission (E)(Rising Sun)', '2004', 'Action / Adventure', 'Nintendo R&D1', '1', 'Action Adventure', 'Non-linear 2D exploration with power-ups and hidden secrets.', 'Revisit Samus''s first mission on Zebes and escape the Space Pirates.', 'A brilliant remake of the original NES Metroid for GBA.', 'Metroid: Zero Mission offers the ultimate 2D Samus experience. Explore a massive world with modern controls and a brand new stealth-focused epilogue.');
