INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid---zero-mission-no-chozo-hints+item-toggle', 'GAMEBOYADVANCE', 'Metroid - Zero Mission [No Chozo Hints+Item Toggle]', '2019', 'Action / Adventure', 'Homebrew', '1', 'ROM Hack', 'Open-ended 2D exploration with a focus on discovery and customization.', 'Complete the game without guidance and toggle items for extra challenge.', 'A "purist" hack that removes hints and allows item management.', 'This Metroid: Zero Mission modification is for veteran fans. Explore Zebes without hand-holding and customize your challenge level with the item toggle feature.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-fusion---better-suits-colours', 'GAMEBOYADVANCE', 'Metroid Fusion - Better Suits Colours', '2018', 'Action / Adventure', 'Homebrew', '1', 'ROM Hack', 'Atmospheric 2D exploration with a revamped visual palette.', 'Explore the BSL station with more vibrant and accurate suit colors.', 'A visual modification for Metroid Fusion improving character sprites.', 'Metroid Fusion: Better Suits Colours fixes the washed-out GBA palette. Enjoy Samus''s various suit upgrades with richer, more iconic colors that pop on modern screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-sr387-10', 'GAMEBOYADVANCE', 'Metroid SR387 1.0', '2021', 'Action / Adventure', 'Homebrew', '1', 'ROM Hack', 'Large-scale 2D exploration with new level designs and map layouts.', 'Navigate a completely redesigned planet to defeat the Metroid threat.', 'A massive total conversion hack of Metroid Fusion.', 'Metroid SR387 is a full-length fan game. Featuring new areas, puzzles, and bosses, it provides a fresh and challenging experience using the Fusion engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metroid-zero-mission---boss-rush-mode', 'GAMEBOYADVANCE', 'Metroid Zero Mission - Boss Rush Mode', '2020', 'Action / Adventure', 'Homebrew', '1', 'ROM Hack', 'Boss-centric action mode featuring all major encounters from the game.', 'Defeat every boss in the game back-to-back as fast as possible.', 'A specialized "Boss Rush" mod for Metroid: Zero Mission.', 'Test your skill in Metroid Zero Mission: Boss Rush Mode. Skip the exploration and go straight to the fight against Ridley, Kraid, and Mother Brain in this intense challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mezase-koushien-jcaravan', 'GAMEBOYADVANCE', 'Mezase Koushien (J)(Caravan)', '2003', 'Sports', 'Konami', '2', 'Baseball Simulation', 'Baseball simulation with high school tournament management.', 'Lead your team to victory in the legendary Koshien tournament.', 'A realistic Japanese high school baseball simulation.', 'Mezase Koushien captures the spirit of Japanese youth baseball. Manage your roster, train your players, and compete for glory in this detailed sports sim for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-no-pocket-resort-jcaravan', 'GAMEBOYADVANCE', 'Mickey no Pocket Resort (J)(Caravan)', '2002', 'Action / Adventure', 'Konami', '1', 'Adventure', 'Collection of vacation-themed mini-games featuring Mickey Mouse.', 'Complete various resort activities to unlock Disney collectibles.', 'A charming Disney-themed mini-game collection for kids.', 'Mickey no Pocket Resort offers a variety of fun, tropical-themed challenges. Join Mickey and friends in this relaxing and colorful handheld vacation experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-epatience', 'GAMEBOYADVANCE', 'Micro Machines (E)(Patience)', '2000', 'Racing', 'Codemasters', '4', 'Arcade Racing', 'Top-down miniature racing with hazard-filled household tracks.', 'Finish first while navigating breakfast tables and pool tables.', 'The classic miniature racing game returns to the GBA.', 'Micro Machines brings high-speed tiny racing to your pocket. Avoid household obstacles and outmaneuver rivals in this addictive and nostalgic top-down racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('midnight-club---street-racing-ednl', 'GAMEBOYADVANCE', 'Midnight Club - Street Racing (E)(DNL)', '2001', 'Racing', 'Angel Studios', '1', 'Street Racing', 'High-speed illegal street racing with an emphasis on shortcuts.', 'Win races across urban cityscapes to become the king of the streets.', 'A handheld version of Rockstar’s famous urban racing series.', 'Midnight Club: Street Racing delivers intense arcade driving. Navigate open-city tracks, find hidden shortcuts, and outrun the competition in this gritty GBA racer.');
