INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('midways-greatest-arcade-hits-umode7', 'GAMEBOYADVANCE', 'Midway''s Greatest Arcade Hits (U)(Mode7)', '2002', 'Compilation', 'Digital Eclipse', '1', 'Arcade Compilation', 'Emulated arcade classics including Defender, Joust, and Robotron.', 'Achieve high scores in perfectly preserved 80s arcade hits.', 'A premium collection of Midway''s most iconic arcade games.', 'Midway''s Greatest Arcade Hits brings the golden age of gaming to GBA. Enjoy pixel-perfect ports of Defender, Sinistar, and more in one essential retro pack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-beanz-pocket-puzzles-urising-sun', 'GAMEBOYADVANCE', 'Mighty Beanz Pocket Puzzles (U)(Rising Sun)', '2004', 'Puzzle', 'Blue 52 Games', '1', 'Puzzle', 'Physics-based puzzle-solving featuring collectible "Beanz" characters.', 'Navigate your Beanz through complex mazes and mechanical traps.', 'A quirky puzzle game based on the popular Mighty Beanz toys.', 'Mighty Beanz Pocket Puzzles combines logic and physics. Tilt and turn your way through challenging levels to collect all the Beanz in this unique handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mijn-dierenpension-esupplex', 'GAMEBOYADVANCE', 'Mijn Dierenpension (E)(sUppLeX)', '2007', 'Simulation', 'Tate Interactive', '1', 'Animal Care Simulation', 'Animal hotel simulation with pet care and facility management.', 'Manage a successful pet pension by keeping every animal happy.', 'A heartwarming animal boarding and care simulation.', 'Mijn Dierenpension lets you run your own pet hotel. Feed, play with, and care for various animals while expanding your business in this charming Dutch sim.');
