INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-farm-advance-jcezar', 'GAMEBOYADVANCE', 'Monster Farm Advance (J)(Cezar)', '2001', 'Simulation', 'Tecmo', '1', 'Monster Raising', 'Creature-raising simulation where monsters are generated from text.', 'Train and fuse monsters to win the world-class fighting tournament.', 'The Japanese version of the acclaimed Monster Rancher series.', 'Monster Farm Advance lets you create monsters using keywords. Train your creatures and compete in intense tactical battles to become a master rancher.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-farm-advance-2-jchakky', 'GAMEBOYADVANCE', 'Monster Farm Advance 2 (J)(Chakky)', '2002', 'Simulation', 'Tecmo', '1', 'Monster Raising', 'Expanded creature-raising simulation with more monsters and modes.', 'Develop the ultimate monster through rigorous training and battle.', 'The deep and engaging sequel to the Japanese Monster Farm sim.', 'Monster Farm Advance 2 offers hundreds of new monster combinations. Refine your training methods and explore new lands in this comprehensive sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-force-elightforce', 'GAMEBOYADVANCE', 'Monster Force (E)(LightForce)', '2002', 'Action', 'Eurocom', '1', 'Action Adventure', 'Top-down action-adventure focusing on monster-slaying and teamwork.', 'Protect the world from classic Universal Monsters as part of the Force.', 'An action-packed game based on the animated series.', 'Join the Monster Force! Control specialized heroes to battle Dracula and the Mummy in this fast-paced, top-down tactical action game for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-force-ueurasia', 'GAMEBOYADVANCE', 'Monster Force (U)(Eurasia)', '2002', 'Action', 'Eurocom', '1', 'Action Adventure', 'Top-down action-adventure focusing on monster-slaying and teamwork.', 'Protect the world from classic Universal Monsters as part of the Force.', 'An action-packed game based on the animated series.', 'Join the Monster Force! Control specialized heroes to battle Dracula and the Mummy in this fast-paced, top-down tactical action game for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-gate-jindependent', 'GAMEBOYADVANCE', 'Monster Gate (J)(Independent)', '2002', 'RPG', 'Gateworks', '1', 'Dungeon RPG', 'Dungeon-crawling RPG with card-based movement and exploration.', 'Navigate deadly labyrinths to reach the gate and defeat the boss.', 'A unique card-driven RPG series from Japan.', 'Monster Gate offers a strategic take on dungeon crawling. Use cards to move, attack, and defend as you explore mysterious towers filled with loot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-gate-2---dai-inaru-dungeon-jrising-sun', 'GAMEBOYADVANCE', 'Monster Gate 2 - Dai Inaru Dungeon (J)(Rising Sun)', '2003', 'RPG', 'Gateworks', '1', 'Dungeon RPG', 'Dungeon-crawling RPG with card-based movement and exploration.', 'Navigate deadly labyrinths to reach the gate and defeat the boss.', 'A unique card-driven RPG series from Japan.', 'Monster Gate 2 features deeper labyrinths and more tactical card play. Explore the Great Dungeon and survive the dangers of this Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-guardians-jrapid-fire', 'GAMEBOYADVANCE', 'Monster Guardians (J)(Rapid Fire)', '2002', 'Action', 'Rapid Fire', '1', 'Action', 'Side-scrolling strategy and monster-battling adventure.', 'Defeat rival guardians by summoning and commanding powerful creatures.', 'A tactical monster-battle game with vibrant Japanese aesthetics.', 'Monster Guardians combines real-time action with strategy. Build your team of guardians and master the battlefield in this rare Japanese GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-house-erising-sun', 'GAMEBOYADVANCE', 'Monster House (E)(Rising Sun)', '2006', 'Action Adventure', 'Artificial Mind & Movement', '1', 'Action Adventure', 'Stealth-based adventure and puzzle-solving set in a living house.', 'Infiltrate the haunted house to rescue your friends and escape.', 'An atmospheric adventure based on the Sony Pictures film.', 'Monster House for GBA captures the suspense of the movie. Switch between characters to use unique gadgets and solve the mysteries of the house.');
