INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-jam---maximum-destruction-eindependent', 'GAMEBOYADVANCE', 'Monster Jam - Maximum Destruction (E)(Independent)', '2002', 'Racing', 'Terminal Reality', '1', 'Off-Road Racing', '3D-style arena vehicle combat with destructive physics.', 'Destroy all rival trucks in the arena using weapons and raw power.', 'A high-octane vehicular combat game featuring licensed trucks.', 'Monster Jam: Maximum Destruction is all about chaos. Choose iconic trucks like Grave Digger and smash your way to victory in this explosive GBA brawler.');
