INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-maker-4---flash-card-jcezar', 'GAMEBOYADVANCE', 'Monster Maker 4 - Flash Card (J)(Cezar)', '2001', 'RPG', 'Success', '1', 'Card RPG', 'Card-based RPG focusing on deck building and character progression.', 'Collect powerful cards to summon monsters and win tactical duels.', 'A fantasy card-battle game with deep customization options.', 'Monster Maker 4: Flash Card offers a complex strategy experience. Build a balanced deck and navigate a fantasy world in this beautifully illustrated RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-maker-4---kira-dice-jcezar', 'GAMEBOYADVANCE', 'Monster Maker 4 - Kira Dice (J)(Cezar)', '2001', 'RPG', 'Success', '1', 'Dice RPG', 'Digital board game and RPG hybrid using dice-based movement.', 'Win the board game quest by defeating monsters and collecting items.', 'A unique dice-rolling RPG adventure set in the Monster Maker world.', 'Monster Maker 4: Kira Dice mixes luck and strategy. Roll your way through dangerous boards and use monster allies to conquer your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-rancher-advance-umode7', 'GAMEBOYADVANCE', 'Monster Rancher Advance (U)(Mode7)', '2001', 'Simulation', 'Tecmo', '1', 'Monster Raising', 'Creature-raising simulation with text-input monster generation.', 'Train your monsters and climb the ranks of the professional leagues.', 'The North American version of the famous Monster Farm series.', 'Monster Rancher Advance brings the addictive "create-and-train" formula to GBA. Use the text-generation system to find rare monsters and lead them to glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-rancher-advance-2-uvenom', 'GAMEBOYADVANCE', 'Monster Rancher Advance 2 (U)(Venom)', '2002', 'Simulation', 'Tecmo', '1', 'Monster Raising', 'Expanded creature-raising simulation with more monsters and modes.', 'Develop the ultimate monster through rigorous training and battle.', 'The definitive North American sequel to Monster Rancher Advance.', 'Monster Rancher Advance 2 features more customization and a massive roster. Experience refined training schedules and deeper battle tactics on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-summoner-jcaravan', 'GAMEBOYADVANCE', 'Monster Summoner (J)(Caravan)', '2002', 'RPG', 'Taito', '1', 'Fantasy RPG', 'Real-time strategy RPG where you summon armies of monsters.', 'Command massive hordes of creatures to conquer the enemy''s base.', 'A unique real-time strategy game with a focus on monster summoning.', 'Monster Summoner offers large-scale tactical battles on the GBA. Manage your mana and summon the right creatures to overwhelm your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-truck-madness-umode7', 'GAMEBOYADVANCE', 'Monster Truck Madness (U)(Mode7)', '2003', 'Racing', 'Terminal Reality', '1', 'Truck Racing', '3D-style racing and stunt driving with massive monster trucks.', 'Win races and perform spectacular stunts to earn points and trophies.', 'A fast-paced racing game based on the PC classic.', 'Monster Truck Madness brings big-wheel action to the GBA. Navigate muddy tracks and crush obstacles in this high-energy racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-trucks-urising-sun', 'GAMEBOYADVANCE', 'Monster Trucks (U)(Rising Sun)', '2004', 'Racing', 'Adrenalin Interactive', '1', 'Truck Racing', 'High-speed arcade racing featuring oversized monster trucks.', 'Outrun your rivals on wild off-road tracks filled with jumps and hazards.', 'An accessible and fun monster truck racing experience.', 'Monster Trucks delivers pure arcade thrills. Master the handling of these massive machines and dominate the dirt tracks in this fast GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-trucks-mayhem-esupplex', 'GAMEBOYADVANCE', 'Monster Trucks Mayhem (E)(sUppLeX)', '2004', 'Racing', 'Adrenalin Interactive', '1', 'Truck Racing', 'Smash-heavy vehicular combat and racing on dangerous tracks.', 'Win the championship by crushing everything in your path.', 'A destructive racing game focused on monster truck mayhem.', 'Monster Trucks Mayhem is for players who love destruction. Use the sheer size of your truck to bulldoze the competition in this intense GBA game.');
