INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monsters-inc-epatience', 'GAMEBOYADVANCE', 'Monsters Inc. (E)(Patience)', '2001', 'Platformer', 'Traveller’s Tales', '1', 'Platform Adventure', 'Side-scrolling platformer with puzzle-solving and "scaring" mechanics.', 'Help Sulley and Mike return Boo to her bedroom while avoiding Randall.', 'An action-adventure based on the beloved Disney/Pixar movie.', 'Monsters, Inc. for GBA lets you play as the top scarers. Navigate the factory, solve puzzles, and protect Boo in this faithful movie adaptation.');
