INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moorhen-3---chicken-chase-evenom', 'GAMEBOYADVANCE', 'Moorhen 3 - Chicken Chase (E)(Venom)', '2004', 'Action', 'Different Games', '1', 'Shooter', 'Point-and-click shooting mechanics focused on reflex speed and accuracy.', 'Shoot down as many moorhens (chickens) as possible within the time limit.', 'Fast-paced poultry shooting gallery for GBA.', 'Experience the classic Moorhen 3: Chicken Chase on GBA. This addictive arcade shooter challenges your reflexes as you hunt chickens across diverse landscapes. Perfect for retro gaming fans looking for high-score hunting and precision shooting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('morita-shogi-advance-jcezar', 'GAMEBOYADVANCE', 'Morita Shogi Advance (J)(Cezar)', '2001', 'Board', 'Game', 'Access', '2', 'Traditional Shogi (Japanese Chess) simulation with strategic AI opponents.', 'Defeat the opponent''s King using tactical piece movements and captures.', 'Authentic Japanese Shogi experience for handheld play.', 'Morita Shogi Advance brings the deep strategy of Japanese Chess to the Game Boy Advance. Featuring advanced AI logic and classic Shogi rules, it''s the definitive portable board game for enthusiasts of strategy and traditional Japanese tabletop games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat---deadly-alliance-eindependent', 'GAMEBOYADVANCE', 'Mortal Kombat - Deadly Alliance (E)(Independent)', '2002', 'Fighting', 'Midway', '2', 'Fighting', '2D side-scrolling fighting game with multiple fighting styles and special moves.', 'Defeat all opponents in the tournament and stop the Deadly Alliance.', 'Portable version of the brutal 3D fighting classic.', 'Mortal Kombat: Deadly Alliance for GBA delivers the visceral combat of the franchise to your pocket. Master unique fighting styles, perform iconic fatalities, and climb the tower to defeat Shang Tsung and Quan Chi in this high-stakes fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat---deadly-alliance-umode7', 'GAMEBOYADVANCE', 'Mortal Kombat - Deadly Alliance (U)(Mode7)', '2002', 'Fighting', 'Midway', '2', 'Fighting', '2D side-scrolling fighting game with multiple fighting styles and special moves.', 'Defeat all opponents in the tournament and stop the Deadly Alliance.', 'Portable version of the brutal 3D fighting classic.', 'Mortal Kombat: Deadly Alliance for GBA delivers the visceral combat of the franchise to your pocket. Master unique fighting styles, perform iconic fatalities, and climb the tower to defeat Shang Tsung and Quan Chi in this high-stakes fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat---tournament-edition-umode7', 'GAMEBOYADVANCE', 'Mortal Kombat - Tournament Edition (U)(Mode7)', '2003', 'Fighting', 'Midway', '2', 'Fighting', 'Weapons-based 2D fighting game featuring exclusive characters and Fatalities.', 'Win the tournament by defeating the most dangerous warriors in the realms.', 'Competitive weapon-focused fighting game for GBA.', 'Mortal Kombat: Tournament Edition expands the GBA roster with deadly new characters. Focus on weapon-based combat, intense 1v1 battles, and the classic gore the series is known for. A must-play for fans of competitive GBA fighting games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-advance-egbanow', 'GAMEBOYADVANCE', 'Mortal Kombat Advance (E)(GBANow)', '2001', 'Fighting', 'Eurocom', '2', 'Fighting', 'Traditional 2D fighting game based on the Ultimate Mortal Kombat 3 engine.', 'Fight through a series of opponents to defeat Shao Kahn.', 'Classic MK3-style fighting action on the go.', 'Mortal Kombat Advance brings the arcade fighting experience to the GBA. Choose from a massive roster of ninjas and warriors, execute combos, and perform fatalities in this port of the legendary fighting franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-advance-uvenom', 'GAMEBOYADVANCE', 'Mortal Kombat Advance (U)(Venom)', '2001', 'Fighting', 'Eurocom', '2', 'Fighting', 'Traditional 2D fighting game based on the Ultimate Mortal Kombat 3 engine.', 'Fight through a series of opponents to defeat Shao Kahn.', 'Classic MK3-style fighting action on the go.', 'Mortal Kombat Advance brings the arcade fighting experience to the GBA. Choose from a massive roster of ninjas and warriors, execute combos, and perform fatalities in this port of the legendary fighting franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mother-1+2-eng-translation', 'GAMEBOYADVANCE', 'Mother 1+2 (Eng. Translation)', '2003', 'RPG', 'HAL Laboratory', '1', 'JRPG', 'Turn-based JRPG with a unique "rhythm-based" battle system and deep story.', 'Travel across the world to stop an evil empire and find your family.', 'Epic and emotional RPG journey with rhythmic combat.', 'Mother 1+2 offers two legendary JRPG experiences in one. Explore a modern-day setting, use psychic powers (PSI), and enjoy a quirky, emotional narrative. This fan-favorite translation brings Earthbound''s roots to English-speaking GBA players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mother-1+2-jtrashman', 'GAMEBOYADVANCE', 'Mother 1+2 (J)(Trashman)', '2003', 'RPG', 'HAL Laboratory', '1', 'JRPG', 'Turn-based JRPG with a unique "rhythm-based" battle system and deep story.', 'Travel across the world to stop an evil empire and find your family.', 'Epic and emotional RPG journey with rhythmic combat.', 'Mother 1+2 offers two legendary JRPG experiences in one. Explore a modern-day setting, use psychic powers (PSI), and enjoy a quirky, emotional narrative. This fan-favorite translation brings Earthbound''s roots to English-speaking GBA players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mother-3-eng-translation', 'GAMEBOYADVANCE', 'Mother 3 (Eng. Translation)', '2006', 'RPG', 'Brownie Brown', '1', 'JRPG', 'Emotional turn-based JRPG featuring a rhythm combo system and character swapping.', 'Pull the Seven Needles to save the Nowhere Islands from destruction.', 'A masterpiece of storytelling and strategic RPG combat.', 'Mother 3 is widely considered one of the best GBA RPGs ever made. Follow Lucas and his companions through a heartbreaking and humorous story. Master the rhythm-based battle mechanics to deal massive damage in this unforgettable cult classic.');
