INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moto-gp-emenace', 'GAMEBOYADVANCE', 'Moto GP (E)(Menace)', '2003', 'Racing', 'Visual Impact', '1', 'Motorcycle Racing', 'Realistic motorcycle racing simulation with professional physics and tracks.', 'Win the World Championship by finishing first in various Grand Prix races.', 'High-speed professional motorcycle racing sim.', 'Moto GP for GBA provides a realistic racing experience, featuring licensed tracks and bikes. Master the racing line, manage your speed through corners, and compete against the world''s best riders in this portable simulation of the premier motorcycling class.');
