INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moto-gp-uindependent', 'GAMEBOYADVANCE', 'Moto GP (U)(Independent)', '2003', 'Racing', 'Visual Impact', '1', 'Motorcycle Racing', 'Realistic motorcycle racing simulation with professional physics and tracks.', 'Win the World Championship by finishing first in various Grand Prix races.', 'High-speed professional motorcycle racing sim.', 'Moto GP for GBA provides a realistic racing experience, featuring licensed tracks and bikes. Master the racing line, manage your speed through corners, and compete against the world''s best riders in this portable simulation of the premier motorcycling class.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moto-gp-&-gt-advance-3-double-pack-eindependent', 'GAMEBOYADVANCE', 'Moto GP & GT Advance 3 Double Pack (E)(Independent)', '2003', 'Racing', 'Visual Impact', '1', 'Motorcycle Racing', 'High-octane motorcycle racing combined with GT car racing across multiple tracks.', 'Dominate both bike and car circuits to become the ultimate racer.', 'Double the speed with both motorcycle and GT car racing.', 'This Moto GP & GT Advance 3 Double Pack offers the best of both worlds. Switch between high-speed bikes and tuned GT cars. Featuring diverse tracks and challenging AI, it’s the ultimate bundle for racing enthusiasts on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motocross-maniacs-advance-jcezar', 'GAMEBOYADVANCE', 'Motocross Maniacs Advance (J)(Cezar)', '2002', 'Racing', 'Konami', '1', 'Motocross', '2D side-scrolling bike racing with stunts, jumps, and combat elements.', 'Reach the finish line while performing stunts and knocking off rivals.', 'Action-packed motocross racing with a stunt focus.', 'Motocross Maniacs Advance takes the classic GB series to new heights. Navigate insane tracks filled with loops and jumps, use nitro boosts, and perform mid-air tricks to outpace your opponents in this frantic 2D racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motocross-maniacs-advance-umode7', 'GAMEBOYADVANCE', 'Motocross Maniacs Advance (U)(Mode7)', '2002', 'Racing', 'Konami', '1', 'Motocross', '2D side-scrolling bike racing with stunts, jumps, and combat elements.', 'Reach the finish line while performing stunts and knocking off rivals.', 'Action-packed motocross racing with a stunt focus.', 'Motocross Maniacs Advance takes the classic GB series to new heights. Navigate insane tracks filled with loops and jumps, use nitro boosts, and perform mid-air tricks to outpace your opponents in this frantic 2D racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motoracer-advance-emode7', 'GAMEBOYADVANCE', 'Motoracer Advance (E)(Mode7)', '2001', 'Racing', 'Delphine Software', '1', 'Motorcycle Racing', 'Arcade-style motorcycle racing with 3D-rendered environments and fast gameplay.', 'Win various street and dirt track races to unlock new bikes and parts.', 'Fast-paced hybrid street and dirt bike racing.', 'Motoracer Advance brings high-speed thrills to the GBA with impressive graphics. Choose between street racing and motocross, drifting through corners and catching air on jumps in one of the most visually impressive racers on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motoracer-advance-usir-vg', 'GAMEBOYADVANCE', 'Motoracer Advance (U)(Sir VG)', '2001', 'Racing', 'Delphine Software', '1', 'Motorcycle Racing', 'Arcade-style motorcycle racing with 3D-rendered environments and fast gameplay.', 'Win various street and dirt track races to unlock new bikes and parts.', 'Fast-paced hybrid street and dirt bike racing.', 'Motoracer Advance brings high-speed thrills to the GBA with impressive graphics. Choose between street racing and motocross, drifting through corners and catching air on jumps in one of the most visually impressive racers on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller-2-eadvance-power', 'GAMEBOYADVANCE', 'Mr. Driller 2 (E)(Advance-Power)', '2001', 'Puzzle', 'Namco', '1', 'Action Puzzle', 'Action-puzzle gameplay focused on digging through colored blocks while managing oxygen.', 'Reach the bottom of the stage without running out of air or being crushed.', 'Addictive digging puzzle action with cute characters.', 'Mr. Driller 2 is the perfect "pick up and play" GBA game. Strategic digging, resource management, and colorful graphics make this a puzzle masterpiece. Compete in different modes to prove you are the fastest driller in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller-2-utrashman', 'GAMEBOYADVANCE', 'Mr. Driller 2 (U)(TrashMan)', '2001', 'Puzzle', 'Namco', '1', 'Action Puzzle', 'Action-puzzle gameplay focused on digging through colored blocks while managing oxygen.', 'Reach the bottom of the stage without running out of air or being crushed.', 'Addictive digging puzzle action with cute characters.', 'Mr. Driller 2 is the perfect "pick up and play" GBA game. Strategic digging, resource management, and colorful graphics make this a puzzle masterpiece. Compete in different modes to prove you are the fastest driller in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller-ace---strange-bacteria-jeurasia', 'GAMEBOYADVANCE', 'Mr. Driller Ace - Strange Bacteria (J)(Eurasia)', '2002', 'Puzzle', 'Namco', '1', 'Action Puzzle', 'Puzzle-platformer featuring Susumu drilling through blocks and fighting bacteria.', 'Clear the screen of blocks and eliminate hazardous bacteria.', 'Enhanced drilling puzzle game with new mechanics.', 'Mr. Driller Ace - Strange Bacteria introduces new challenges to the classic formula. Navigate complex block layouts, manage your air supply, and use new power-ups to clear levels in this polished GBA puzzle sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-incredible---kyouteki-under-minor-toujyou-jwrg', 'GAMEBOYADVANCE', 'Mr. Incredible - Kyouteki Under Minor Toujyou (J)(WRG)', '2004', 'Action', 'Heavy Iron Studios', '1', 'Action Adventure', 'Action-platformer featuring the super-powered members of the Parr family.', 'Stop Syndrome and his robots to save the city and the family.', 'Heroic action-platforming based on the Pixar film.', 'The Incredibles on GBA lets you play as Mr. Incredible and Dash. Use super-strength and speed to battle through levels based on the movie. A solid action title for fans of the Disney-Pixar universe looking for portable heroics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-incredible-jindependent', 'GAMEBOYADVANCE', 'Mr. Incredible (J)(Independent)', '2004', 'Action', 'Heavy Iron Studios', '1', 'Action Adventure', 'Action-platformer featuring the super-powered members of the Parr family.', 'Stop Syndrome and his robots to save the city and the family.', 'Heroic action-platforming based on the Pixar film.', 'The Incredibles on GBA lets you play as Mr. Incredible and Dash. Use super-strength and speed to battle through levels based on the movie. A solid action title for fans of the Disney-Pixar universe looking for portable heroics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-nutz-erising-sun', 'GAMEBOYADVANCE', 'Mr. Nutz (E)(Rising Sun)', '1994', 'Platformer', 'Ocean Software', '1', 'Platformer', '2D side-scrolling platformer featuring a squirrel with a magical hat.', 'Travel through diverse worlds to stop the evil Mr. Blizzard.', 'Classic colorful 16-bit style platforming adventure.', 'Mr. Nutz returns on the GBA with vibrant graphics and challenging levels. Jump, tail-whip, and explore secret areas in this charming platformer that captures the gold standard of 90s mascot-driven adventure games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-maze-madness-erising-sun', 'GAMEBOYADVANCE', 'Ms. Pac-Man Maze Madness (E)(Rising Sun)', '2001', 'Puzzle', 'Mass Media', '1', 'Maze Puzzle', '3D-perspective maze navigation with classic Pac-Man pellet-eating mechanics.', 'Navigate through complex mazes, avoid ghosts, and reach the exit.', 'A modern 3D twist on the classic Pac-Man formula.', 'Ms. Pac-Man Maze Madness brings a fresh perspective to the series. Solve puzzles, navigate moving platforms, and outsmart ghosts in varied themed worlds. It''s a perfect blend of classic arcade action and modern adventure-style gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-maze-madness-uvenom', 'GAMEBOYADVANCE', 'Ms. Pac-Man Maze Madness (U)(Venom)', '2001', 'Puzzle', 'Mass Media', '1', 'Maze Puzzle', '3D-perspective maze navigation with classic Pac-Man pellet-eating mechanics.', 'Navigate through complex mazes, avoid ghosts, and reach the exit.', 'A modern 3D twist on the classic Pac-Man formula.', 'Ms. Pac-Man Maze Madness brings a fresh perspective to the series. Solve puzzles, navigate moving platforms, and outsmart ghosts in varied themed worlds. It''s a perfect blend of classic arcade action and modern adventure-style gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mucha-lucha-mascaritas-of-the-lost-code-umode7', 'GAMEBOYADVANCE', 'Mucha Lucha Mascaritas of the Lost Code (U)(Mode7)', '2003', 'Action', 'Gotham Games', '1', 'Action Platformer', '2D platforming and wrestling combat using "Lucha Libre" style moves.', 'Recover the "Lost Code" and defeat rival luchadores.', 'Action-packed wrestling platformer based on the cartoon.', 'Mucha Lucha: Mascaritas of the Lost Code brings the wacky world of Lucha Libre to GBA. Play as Ricochet, Buena Girl, and The Flea in a quest to recover the Lost Code. Featuring signature moves and vibrant graphics, it''s a must-play for fans of the hit animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mugen-kikou-zero-tours-jeurasia', 'GAMEBOYADVANCE', 'Mugen Kikou Zero Tours (J)(Eurasia)', '2002', 'Action', 'Ascii', '1', 'Mecha Action', 'Turn-based JRPG mechanics with exploration and menu-driven combat.', 'Explore vast worlds and complete quests within a fantasy setting.', 'Classic Japanese handheld JRPG adventure.', 'Mugen Kikou Zero Tours is a deep Japanese JRPG for the Game Boy Advance. Experience a grand adventure with strategic turn-based battles, character progression, and a rich storyline. A hidden gem for collectors of Japanese GBA imports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mugenborg-jpolla', 'GAMEBOYADVANCE', 'Mugenborg (J)(Polla)', '2003', 'Action', 'Ascii', '1', 'Mecha Action', 'Action-oriented combat featuring customizable robotic units.', 'Battle through stages to upgrade your robot and defeat enemies.', 'High-speed robot combat and customization.', 'Mugenborg delivers intense mecha action on the GBA. Control powerful robotic warriors, upgrade your arsenal, and master various combat techniques. Ideal for fans of sci-fi action and fast-paced Japanese handheld games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muppet-pinball-mayhem-eindependent', 'GAMEBOYADVANCE', 'Muppet Pinball Mayhem (E)(Independent)', '2002', 'Pinball', 'Gravity-i', '1', 'Pinball', 'Classic pinball simulation with themed tables and Muppet characters.', 'Score points by hitting targets and completing table-specific missions.', 'Muppet-themed arcade pinball fun.', 'Muppet Pinball Mayhem brings Kermit and the gang to the silver ball. Navigate colorful tables inspired by Muppet locations, unlock bonuses, and aim for the high score in this addictive arcade simulation for the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muppet-pinball-mayhem-uvenom', 'GAMEBOYADVANCE', 'Muppet Pinball Mayhem (U)(Venom)', '2002', 'Pinball', 'Gravity-i', '1', 'Pinball', 'Classic pinball simulation with themed tables and Muppet characters.', 'Score points by hitting targets and completing table-specific missions.', 'Muppet-themed arcade pinball fun.', 'Muppet Pinball Mayhem brings Kermit and the gang to the silver ball. Navigate colorful tables inspired by Muppet locations, unlock bonuses, and aim for the high score in this addictive arcade simulation for the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muppets---on-with-the-show-ueurasia', 'GAMEBOYADVANCE', 'Muppets - On With The Show (U)(Eurasia)', '2003', 'Action', 'Disney Interactive', '1', 'Action Platformer', 'Variety of mini-games including rhythm, puzzle, and action challenges.', 'Complete a series of show-themed activities to put on a great performance.', 'Collection of Muppet-themed variety mini-games.', 'The Muppets: On With The Show features a wide array of activities starring your favorite characters. From Kermit to Miss Piggy, engage in fun challenges that test your timing and skill in this family-friendly GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muscular-ranking-jeurasia', 'GAMEBOYADVANCE', 'Muscular Ranking (J)(Eurasia)', '2003', 'Party', 'Game', 'Konami', '1', 'Sports simulation based on a Japanese physical challenge TV show.', 'Complete rigorous physical training and obstacle courses to rank up.', 'Intense physical challenge sports simulation.', 'Muscular Ranking (Kinniku Banzuke) brings the famous Japanese TV challenge to GBA. Test your timing and endurance across multiple mini-games designed to push your digital athlete to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mutsu-water-looper-jindependent', 'GAMEBOYADVANCE', 'Mutsu Water Looper (J)(Independent)', '2001', 'Action', 'Nintendo', '1', 'Arcade Action', 'Virtual pet simulation focused on aquatic and land-based creatures.', 'Raise, feed, and care for Mutsu to ensure its growth and happiness.', 'Relaxing creature-raising simulation.', 'Mutsu Water Looper is a unique virtual pet experience. Interact with your Mutsu in diverse environments, keep it healthy, and watch it evolve. A peaceful and charming title for fans of digital pet games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mx-2002-featuring-ricky-carmichael-umode7', 'GAMEBOYADVANCE', 'MX 2002 Featuring Ricky Carmichael (U)(Mode7)', '2001', 'Racing', 'Climax Studios', '1', 'Motocross Racing', 'Motocross racing with realistic physics, stunts, and licensed tracks.', 'Win championships and earn points by performing insane tricks.', 'Professional motocross racing with Ricky Carmichael.', 'MX 2002 delivers high-flying motocross action to the GBA. Compete as the legendary Ricky Carmichael, master the stunt system, and conquer challenging dirt tracks in this definitive portable racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-animal-centre-in-africa-erising-sun', 'GAMEBOYADVANCE', 'My Animal Centre in Africa (E)(Rising Sun)', '2006', 'Simulation', 'Independent Arts', '1', 'Animal Care', 'Life simulation and management focused on wildlife veterinary care.', 'Heal injured animals and manage a sanctuary in the African savanna.', 'Wildlife rescue and veterinary simulation.', 'My Animal Centre in Africa puts you in charge of a safari clinic. Care for lions, elephants, and zebras, diagnose illnesses, and expand your facilities in this educational and heartwarming simulation game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-little-pony-crystal-princess---the-runaway-rainbow-urising-sun', 'GAMEBOYADVANCE', 'My Little Pony Crystal Princess - The Runaway Rainbow (U)(Rising Sun)', '2006', 'Adventure', 'Climax Studios', '1', 'Adventure', 'Adventure-platformer with mini-games focused on pony care and magic.', 'Help the ponies find the Runaway Rainbow to save the celebration.', 'Magical pony adventure for younger players.', 'My Little Pony: Crystal Princess features exploration and friendship-themed challenges. Help the ponies of Ponyville navigate beautiful levels and complete tasks in this colorful and accessible GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-pet-hotel-erising-sun', 'GAMEBOYADVANCE', 'My Pet Hotel (E)(Rising Sun)', '2006', 'Simulation', 'Independent Arts', '1', 'Animal Care', 'Simulation game focused on managing a hotel for various pets.', 'Care for cats, dogs, and horses to become the best pet hotel manager.', 'Pet boarding and management simulation.', 'My Pet Hotel allows you to run your own animal sanctuary. Groom, feed, and play with different pets while managing your business''s reputation. A perfect title for animal lovers who enjoy management games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-mahjan-kaburiichi-jnil', 'GAMEBOYADVANCE', 'Nakayoshi Mahjan Kaburiichi (J)(NIL)', '2001', 'Mahjong', 'Unknown', '1', 'Mahjong', 'Traditional Japanese Mahjong with competitive AI and cute characters.', 'Win hands by building sets and sequences to defeat opponents.', 'Strategic Japanese Mahjong board game.', 'Nakayoshi Mahjan Kaburiichi offers an authentic Riichi Mahjong experience. Featuring characters from the Nakayoshi magazine, it blends deep strategy with a charming aesthetic for fans of traditional board games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-pet-advance-series-1-kawaii-hamster-jchakky', 'GAMEBOYADVANCE', 'Nakayoshi Pet Advance Series 1 Kawaii Hamster (J)(Chakky)', '2002', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focused on raising and breeding hamsters.', 'Keep your hamster happy and healthy through care and mini-games.', 'Cute hamster raising simulation.', 'Part of the Nakayoshi series, this game focuses on the daily care of adorable hamsters. Clean their cages, feed them, and play mini-games to build a bond with your digital pet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-pet-advance-series-2-kawaii-koinu-jchakky', 'GAMEBOYADVANCE', 'Nakayoshi Pet Advance Series 2 Kawaii Koinu (J)(Chakky)', '2002', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focused on raising and caring for puppies.', 'Train and care for your puppy to become a loyal companion.', 'Adorable puppy raising and training sim.', 'Raise the perfect puppy in Nakayoshi Pet Advance Series 2. Learn the responsibilities of pet ownership by feeding, walking, and training your dog in this charming Japanese handheld simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-pet-advance-series-3-kawaii-koneko-jchakky', 'GAMEBOYADVANCE', 'Nakayoshi Pet Advance Series 3 Kawaii Koneko (J)(Chakky)', '2002', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focused on raising and caring for kittens.', 'Provide love and care to your kitten to ensure it grows up healthy.', 'Sweet kitten raising and care simulation.', 'Focus on the feline world with Nakayoshi Pet Advance Series 3. Experience the joy of raising a kitten, from playtime to grooming, in this dedicated pet simulation for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-pet-advance-series-3-kawaii-koneko-jindependent', 'GAMEBOYADVANCE', 'Nakayoshi Pet Advance Series 3 Kawaii Koneko (J)(Independent)', '2002', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation focused on raising and caring for kittens.', 'Provide love and care to your kitten to ensure it grows up healthy.', 'Sweet kitten raising and care simulation.', 'Focus on the feline world with Nakayoshi Pet Advance Series 3. Experience the joy of raising a kitten, from playtime to grooming, in this dedicated pet simulation for the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-pet-advance-series-4---kawaii-koinu-kogatainuhen-jevasion', 'GAMEBOYADVANCE', 'Nakayoshi Pet Advance Series 4 - Kawaii Koinu Kogatainuhen (J)(Evasion)', '2002', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Virtual pet simulation specialized in small-breed puppies.', 'Manage the specific needs of small dog breeds and train them.', 'Specialized small-breed puppy care sim.', 'This entry in the Nakayoshi series focuses exclusively on small dog breeds. Learn about the unique traits of various small puppies while providing expert care and training in this detailed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nakayoshi-youchien-jchakky', 'GAMEBOYADVANCE', 'Nakayoshi Youchien (J)(Chakky)', '2003', 'Simulation', 'MTO', '1', 'Life Simulation', 'Life simulation focused on daily activities in a kindergarten setting.', 'Complete educational tasks and interact with other children.', 'Kindergarten life and education simulation.', 'Nakayoshi Youchien offers a glimpse into the daily life of a preschooler. Engage in fun educational mini-games, make friends, and participate in school activities in this gentle Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum---50th-anniversary-utrashman', 'GAMEBOYADVANCE', 'Namco Museum - 50th Anniversary (U)(Trashman)', '2001', 'Compilation', 'Namco', '1', 'Arcade Compilation', 'Arcade collection featuring classics like Pac-Man, Galaga, and Dig Dug.', 'Achieve high scores in various legendary Namco arcade titles.', 'Essential collection of retro arcade classics.', 'Namco Museum 50th Anniversary brings the arcade home. Enjoy pixel-perfect ports of Pac-Man, Galaga, Dig Dug, and more. A must-have for retro gaming fans who want the best of the 80s on their GBA.');
