INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nancy-drew---message-in-a-haunted-mansion-ueurasia', 'GAMEBOYADVANCE', 'Nancy Drew - Message in a Haunted Mansion (U)(Eurasia)', '2001', 'Adventure', 'Torus Games', '1', 'Adventure', 'Point-and-click mystery adventure with puzzle-solving and exploration.', 'Investigate a haunted mansion to uncover the truth behind the ghosts.', 'Supernatural mystery and puzzle adventure.', 'Nancy Drew: Message in a Haunted Mansion brings the famous detective to GBA. Solve intricate puzzles, interview suspects, and explore a spooky Victorian mansion in this engaging handheld mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('napoleon---laigle-de-guerre-fpatience', 'GAMEBOYADVANCE', 'Napoleon - L''Aigle de Guerre (F)(Patience)', '2003', 'Strategy', 'Genki', '1', 'Turn-Based Strategy', 'Real-time strategy and tactical combat based on historical battles.', 'Lead the French army to victory across Europe as Napoleon.', 'Historical RTS and tactical warfare.', 'Napoleon: L''Aigle de Guerre (known as Napoleon in Japan) is a rare GBA RTS. Command infantry, cavalry, and artillery in large-scale battles. A deep tactical experience for fans of military history and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('napoleon-jcapital', 'GAMEBOYADVANCE', 'Napoleon (J)(Capital)', '2001', 'Strategy', 'Genki', '1', 'Turn-Based Strategy', 'Real-time strategy and tactical combat based on historical battles.', 'Lead the French army to victory across Europe as Napoleon.', 'Historical RTS and tactical warfare.', 'Napoleon: L''Aigle de Guerre (known as Napoleon in Japan) is a rare GBA RTS. Command infantry, cavalry, and artillery in large-scale battles. A deep tactical experience for fans of military history and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---konoha-senki-jcezar', 'GAMEBOYADVANCE', 'Naruto - Konoha Senki (J)(Cezar)', '2003', 'Strategy', 'Tomy', '1', 'Tactical Strategy', 'Tactical grid-based strategy with RPG elements and story cutscenes.', 'Lead Naruto and his team through the events of the Hidden Leaf village.', 'Tactical strategy RPG set in the Naruto universe.', 'Naruto: Konoha Senki offers a strategic take on the ninja world. Control your favorite characters on a grid, use Ninjutsu, and follow the anime''s storyline in this Japan-exclusive tactical RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto---ninja-council-utrashman', 'GAMEBOYADVANCE', 'Naruto - Ninja Council (U)(Trashman)', '2003', 'Action', 'Tomy', '1', 'Action Platformer', '2D side-scrolling action platformer with ninja combat and support calls.', 'Defeat enemies and bosses to progress through the ninja training arc.', 'Fast-paced ninja action platformer.', 'Naruto: Ninja Council brings the high-energy combat of the anime to GBA. Use Naruto or Sasuke, wall-run, and unleash powerful jutsu to defeat Orochimaru’s forces in this classic handheld action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-jeurasia', 'GAMEBOYADVANCE', 'Naruto (J)(Eurasia)', '2003', 'Action', 'Tomy', '1', 'Action Platformer', '2D side-scrolling action platformer with ninja combat and support calls.', 'Defeat enemies and bosses to progress through the ninja training arc.', 'Fast-paced ninja action platformer.', 'Naruto: Ninja Council brings the high-energy combat of the anime to GBA. Use Naruto or Sasuke, wall-run, and unleash powerful jutsu to defeat Orochimaru’s forces in this classic handheld action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-ninja-council-2-urising-sun', 'GAMEBOYADVANCE', 'Naruto Ninja Council 2 (U)(Rising Sun)', '2004', 'Action', 'Tomy', '1', 'Action Platformer', '2D side-scrolling action with a larger roster and team-based attacks.', 'Fight through the Chuunin Exams and beyond to protect the village.', 'Enhanced ninja combat and platforming sequel.', 'Naruto: Ninja Council 2 improves on every aspect of the first game. Featuring a bigger roster including Sakura and Kakashi, it offers intense boss battles and smoother ninja movement for the ultimate GBA Naruto experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-rpg---uketsugareshi-hi-no-ishi-jindependent', 'GAMEBOYADVANCE', 'Naruto RPG - Uketsugareshi Hi no Ishi (J)(Independent)', '2004', 'RPG', 'Dimps', '1', 'Action RPG', 'Turn-based JRPG with exploration and team-building mechanics.', 'Journey through the Naruto world and fulfill your destiny as a ninja.', 'Deep turn-based JRPG set in the Naruto world.', 'Naruto RPG: Uketsugareshi Hi no Ishi is a traditional role-playing game. Build your team, explore iconic locations, and engage in strategic turn-based battles using the series'' famous special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto-saikyou-ninja-daikessyu-2-jeurasia', 'GAMEBOYADVANCE', 'Naruto Saikyou Ninja Daikessyu 2 (J)(Eurasia)', '2004', 'Action', 'Tomy', '1', 'Action Platformer', '2D fighting and action platforming with multiple playable ninjas.', 'Conquer the ninja tournament and defeat powerful enemies.', 'Action-heavy ninja fighting game.', 'Known as Ninja Council 2 in the West, this Japanese version features intense action and a deep story mode. Master the art of the ninja and prove your strength in this definitive GBA action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-heat-2002-uvenom', 'GAMEBOYADVANCE', 'NASCAR Heat 2002 (U)(Venom)', '2001', 'Racing', 'Monster Games', '1', 'NASCAR Racing', 'High-speed stock car racing with drafting and pit-stop mechanics.', 'Win the NASCAR Cup by outperforming rivals on official oval tracks.', 'Authentic NASCAR stock car racing simulation.', 'NASCAR Heat 2002 brings the roar of the engines to your GBA. Featuring official drivers and tracks, this racer focuses on strategic drafting and high-speed precision. Experience the intensity of professional stock car racing in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('natural-2-duo-jkamx', 'GAMEBOYADVANCE', 'Natural 2 Duo (J)(KaMX)', '2003', 'Adventure', 'Spike', '1', 'Visual Novel', 'Visual novel adventure with choice-based branching narratives.', 'Progress through the story and build relationships with characters.', 'Japanese visual novel and romantic adventure.', 'Natural 2 Duo is a classic Japanese adventure game for GBA. Navigate complex social situations and make choices that determine the outcome of the story. A beautifully illustrated title for fans of the visual novel genre and interactive storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-2002-umode7', 'GAMEBOYADVANCE', 'NBA Jam 2002 (U)(Mode7)', '2002', 'Sports', 'Iguana Entertainment', '4', 'Arcade Basketball', '2-on-2 arcade basketball with "on-fire" mechanics and massive dunks.', 'Outscore the opponent using high-flying moves and aggressive defense.', 'Fast-paced over-the-top arcade basketball action.', 'NBA Jam 2002 brings the legendary arcade hoops experience to the GBA. Execute gravity-defying dunks, push opponents, and get "on fire" in this classic 2v2 sports game. It’s pure, unfiltered basketball fun without the rules of a simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---porsche-unleashed-esuxxors', 'GAMEBOYADVANCE', 'Need For Speed - Porsche Unleashed (E)(Suxxors)', '2000', 'Racing', 'Eden Studios', '1', 'Simulation Racing', 'Evolution-based racing focusing on the history of Porsche cars.', 'Unlock and drive iconic Porsche models through various eras.', 'Detailed racing tribute to the Porsche brand.', 'Need For Speed: Porsche Unleashed on GBA celebrates the legacy of the German manufacturer. Drive classic and modern Porsches across scenic European tracks. Master the handling of each car in this specialized entry of the NFS franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---porsche-unleashed-uindependent', 'GAMEBOYADVANCE', 'Need For Speed - Porsche Unleashed (U)(Independent)', '2000', 'Racing', 'Eden Studios', '1', 'Simulation Racing', 'Evolution-based racing focusing on the history of Porsche cars.', 'Unlock and drive iconic Porsche models through various eras.', 'Detailed racing tribute to the Porsche brand.', 'Need For Speed: Porsche Unleashed on GBA celebrates the legacy of the German manufacturer. Drive classic and modern Porsches across scenic European tracks. Master the handling of each car in this specialized entry of the NFS franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed---underground-umode7', 'GAMEBOYADVANCE', 'Need For Speed - Underground (U)(Mode7)', '2003', 'Racing', 'Pocketeers', '1', 'Street Racing', 'Arcade street racing with car customization and nitro boosts.', 'Rise through the underground ranks and become the top street racer.', 'Intense night-time street racing and tuning.', 'Need For Speed Underground brings the tuner culture to the GBA. Customize your car''s performance and looks, then hit the streets in high-stakes night races. Experience the speed and style that defined an era of racing games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed-carbon---own-the-city-urising-sun', 'GAMEBOYADVANCE', 'Need for Speed Carbon - Own the City (U)(Rising Sun)', '2006', 'Racing', 'EA Canada', '1', 'Street Racing', 'Open-world style racing with a focus on crew management and territory.', 'Take over the city''s districts by winning street races.', 'Crew-based street racing in an urban setting.', 'Need for Speed Carbon: Own the City focuses on territorial control. Build your crew, outrun the police, and dominate the streets of Coast City. This GBA version offers a unique narrative and fast-paced arcade driving mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed-most-wanted-urising-sun', 'GAMEBOYADVANCE', 'Need for Speed Most Wanted (U)(Rising Sun)', '2005', 'Racing', 'EA Canada', '1', 'Street Racing', 'High-speed police chases and illegal street racing.', 'Become the most wanted racer by defeating Blacklist rivals.', 'Thrilling police pursuit and street racing action.', 'Need for Speed Most Wanted for GBA combines the thrill of street racing with intense police chases. Evade the law, win races, and climb the Blacklist to prove you are the most notorious driver on the road.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('need-for-speed-underground-2-uvenom', 'GAMEBOYADVANCE', 'Need for Speed Underground 2 (U)(Venom)', '2004', 'Racing', 'Pocketeers', '1', 'Street Racing', 'Career-based street racing with deep visual and performance tuning.', 'Become the best racer in the city by winning diverse event types.', 'The ultimate street racing and customization sim.', 'Need for Speed Underground 2 expands the tuner experience on GBA. With improved physics and more customization options, players can create their dream machine and compete in various race modes to dominate the underground scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-blitz-20-03-uvenom', 'GAMEBOYADVANCE', 'NFL Blitz 20-03 (U)(Venom)', '2002', 'Sports', 'Midway', '4', 'Arcade Football', 'Aggressive 7-on-7 football with no rules and late hits.', 'Outscore the opponent in a brutal and fast-paced football game.', 'Over-the-top arcade American football action.', 'NFL Blitz 20-03 is football without the penalties. Execute massive tackles, long passes, and late hits in this high-energy arcade sports game. Fast, fun, and perfect for quick sessions on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-blitz-2002-uquartex', 'GAMEBOYADVANCE', 'NFL Blitz 2002 (U)(Quartex)', '2001', 'Sports', 'Midway', '4', 'Arcade Football', 'Aggressive 7-on-7 football with no rules and late hits.', 'Outscore the opponent in a brutal and fast-paced football game.', 'Over-the-top arcade American football action.', 'NFL Blitz 2002 brings the hard-hitting arcade football experience to the palm of your hand. Forget the playbook and focus on big plays and even bigger hits in this classic Midway sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhl-hitz-20-03-uindependent', 'GAMEBOYADVANCE', 'NHL Hitz 20-03 (U)(Independent)', '2002', 'Sports', 'Black Box Games', '4', 'Arcade Hockey', 'Hard-hitting 3-on-3 arcade hockey with power-ups and body checks.', 'Score more goals than the opposition while playing aggressively.', 'Fast-paced, aggressive arcade hockey simulation.', 'NHL Hitz 20-03 delivers high-intensity hockey action for the GBA. With 3v3 gameplay and no-holds-barred checking, it’s a fast and furious take on the sport. Fire up the ice and score goals in this fan-favorite arcade sports port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---attack-of-the-toybots-usir-vg', 'GAMEBOYADVANCE', 'Nicktoons - Attack of the Toybots (U)(Sir VG)', '2007', 'Action', 'Blue Tongue Entertainment', '1', 'Action Platformer', '2D action-platforming featuring a crossover of Nickelodeon characters.', 'Stop the evil Professor Calamitous and his army of toybots.', 'Heroic crossover adventure with Nicktoons stars.', 'Nicktoons: Attack of the Toybots features Danny Phantom, SpongeBob, and more. Battle through robot-infested levels and use unique character abilities to save the multiverse in this fun and colorful GBA platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---battle-for-volcano-island-urising-sun', 'GAMEBOYADVANCE', 'Nicktoons - Battle for Volcano Island (U)(Rising Sun)', '2006', 'Action', 'Blue Tongue Entertainment', '1', 'Action Platformer', 'Isometric action-adventure with combat and puzzle-solving elements.', 'Defeat the Mawgu and save Volcano Island from destruction.', 'Tropical adventure starring favorite Nicktoons heroes.', 'Nicktoons: Battle for Volcano Island brings SpongeBob, Danny Phantom, and Timmy Turner together. Explore the island, fight enemies, and solve environmental puzzles in this cooperative-style adventure for the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---freeze-frame-frenzy-erising-sun', 'GAMEBOYADVANCE', 'Nicktoons - Freeze Frame Frenzy (E)(Rising Sun)', '2004', 'Party', 'Nickelodeon', '1', 'Mini-games', 'Photography-based puzzle game where you capture moments on film.', 'Take photos of specific characters and items to solve the mystery.', 'Unique photography-themed puzzle adventure.', 'Nicktoons: Freeze Frame Frenzy is a creative take on the franchise. Travel through different Nicktoons worlds and snap the perfect photos to progress. It’s a refreshing break from standard platformers, featuring a huge cast of characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons---freeze-frame-frenzy-urising-sun', 'GAMEBOYADVANCE', 'Nicktoons - Freeze Frame Frenzy (U)(Rising Sun)', '2004', 'Party', 'Nickelodeon', '1', 'Mini-games', 'Photography-based puzzle game where you capture moments on film.', 'Take photos of specific characters and items to solve the mystery.', 'Unique photography-themed puzzle adventure.', 'Nicktoons: Freeze Frame Frenzy is a creative take on the franchise. Travel through different Nicktoons worlds and snap the perfect photos to progress. It’s a refreshing break from standard platformers, featuring a huge cast of characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons-racing-epatience', 'GAMEBOYADVANCE', 'Nicktoons Racing (E)(Patience)', '2000', 'Racing', 'ATeam', '4', 'Cart Racing', 'Kart racing with power-ups and themed tracks from Nicktoons.', 'Finish in first place across various Nickelodeon-themed circuits.', 'Wacky kart racing with iconic cartoon characters.', 'Nicktoons Racing puts you behind the wheel with characters like Rugrats and Hey Arnold. Use crazy power-ups, discover shortcuts, and compete in multiple modes to become the champion of the Nicktoons circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons-racing-uvenom', 'GAMEBOYADVANCE', 'Nicktoons Racing (U)(Venom)', '2000', 'Racing', 'ATeam', '4', 'Cart Racing', 'Kart racing with power-ups and themed tracks from Nicktoons.', 'Finish in first place across various Nickelodeon-themed circuits.', 'Wacky kart racing with iconic cartoon characters.', 'Nicktoons Racing puts you behind the wheel with characters like Rugrats and Hey Arnold. Use crazy power-ups, discover shortcuts, and compete in multiple modes to become the champion of the Nicktoons circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nicktoons-unite-utrashman', 'GAMEBOYADVANCE', 'Nicktoons Unite (U)(Trashman)', '2006', 'Action', 'Blue Tongue Entertainment', '1', 'Action Platformer', '2D platforming and combat with character-switching mechanics.', 'Stop the Syndicate from taking over the Nicktoons universe.', 'Multiverse crossover platforming action.', 'Nicktoons Unite! brings the ultimate team of SpongeBob, Danny Phantom, Timmy Turner, and Jimmy Neutron to the GBA. Switch between heroes to use their specific skills and stop the combined forces of their greatest villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-cop-eadvance-power', 'GAMEBOYADVANCE', 'Ninja Cop (E)(Advance-Power)', '2002', 'Action', 'Konami', '1', 'Action Platformer', 'High-speed 2D action platformer with sword combat and gadgets.', 'Infiltrate criminal hideouts and take down the syndicate.', 'Incredible ninja action platformer (Ninja Five-0).', 'Ninja Cop (known as Ninja Five-0 in the US) is a cult classic. Use your grappling hook and katana to navigate levels and rescue hostages. It is widely considered one of the best and most sought-after action games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-five-0-utrashman', 'GAMEBOYADVANCE', 'Ninja Five-0 (U)(Trashman)', '2003', 'Action', 'Hudson Soft', '1', 'Action Platformer', 'High-speed 2D action platformer with sword combat and gadgets.', 'Infiltrate criminal hideouts and take down the syndicate.', 'Incredible ninja action platformer (Ninja Five-0).', 'Ninja Five-0 is a masterpiece of GBA action gaming. Combining precise platforming with intense combat and hostage rescue, it offers a challenge that few other handheld games can match. A true gem for action game enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nishihara-rieko-no-tendou-maajan-jindependent', 'GAMEBOYADVANCE', 'Nishihara Rieko no Tendou Maajan (J)(Independent)', '2001', 'Mahjong', 'Unknown', '1', 'Mahjong', 'Traditional Japanese Mahjong with a quirky art style.', 'Defeat opponents in Mahjong matches to progress through the game.', 'Quirky Japanese Mahjong board game.', 'Nishihara Rieko no Tendou Maajan offers a unique take on the classic board game. Featuring the art and humor of Rieko Nishihara, it’s a solid Mahjong sim with plenty of personality for the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('no-bitches?', 'GAMEBOYADVANCE', 'No Bitches?', '2003', 'Action', 'Unknown', '1', 'Action', 'Humorous or meme-based interaction (contextual interpretation).', 'Navigate social or humorous challenges based on the popular meme.', 'A meme-inspired interactive experience.', 'No Bitches? is a specialized digital experience based on the popular internet meme. It serves as a humorous addition to a collection, reflecting internet culture of the era through the lens of the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('no-rules-get-phat-ulightforce', 'GAMEBOYADVANCE', 'No Rules Get Phat (U)(Lightforce)', '2001', 'Sports', 'Humagade', '2', 'Arcade Sports', '2D platformer with extreme sports and skateboarding mechanics.', 'Complete levels by performing tricks and reaching the goal.', 'Urban-themed extreme sports platformer.', 'No Rules Get Phat is a stylized platformer that blends skating culture with action. Grind rails, perform tricks, and take down enemies in this uniquely urban GBA title that captures the early 2000s "extreme" aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nobunaga-ibun-jindependent', 'GAMEBOYADVANCE', 'Nobunaga Ibun (J)(Independent)', '2002', 'Strategy', 'Koei', '1', 'Historical Strategy', 'Tactical turn-based strategy set in historical Japan.', 'Conquer feudal Japan through military and political strategy.', 'Deep historical strategy RPG (Nobunaga).', 'Nobunaga Ibun is a specialized tactical RPG. Command armies, manage resources, and engage in turn-based combat to unify Japan. It’s a rewarding experience for fans of historical strategy and deep menu-driven gameplay.');